/* SPDX-License-Identifier: GPL-2.0-only */
/* Same original factory TU, after the existing actual typed/retained owners.
 * Scan and bind are separate one-shot phases of the SAME prepaid bank. No
 * adopted device, replacement actor/deadline, worker or second owner table. */
#include <net/lsf_stream_constructor_private.h>

static struct lsf_prepaid_view *lsf_stream_vp_record_locked(
    struct lsf_stream_rx_state *, const void *, struct lsf_prepaid_ticket *);

int lsf_factory_stream_constructor_mode(void)
{
    /* Policy selection only. Every caller retains its actual typed source
     * guard and original mutation lock; this grants no allocation authority. */
    return lsf_factory_selected_consumer() != NULL;
}

static struct lsf_prepaid_view *lsf_stream_pci_record_locked(
    struct lsf_stream_rx_state *state, const struct pci_dev *pci,
    struct lsf_prepaid_ticket *ticket, unsigned int allow_queued)
{
    struct lsf_prepaid_view *r;
    unsigned long base, at = (unsigned long)pci;
    unsigned int i;
    lockdep_assert_held(&pool_lock);
    if (!state || state != lsf_stream_rx_current_locked() || !ticket ||
        !lsf_stream_rx_address_locked(pci)) return NULL;
    base = (unsigned long)page_address(factory.pages);
    for (i = 1; i < LSF_ALLOCATION_SLOTS; ++i) {
        r = &factory.pool.records[i];
        if (r->offset != at - base || r->kind != LSF_DEVICE_PCI) continue;
        *ticket = (struct lsf_prepaid_ticket){i, r->generation};
        if (r->bytes < sizeof(*pci) ||
            (r->deferred != LSF_PREPAID_PUBLISHED &&
             !(allow_queued && r->deferred == LSF_PREPAID_QUEUED)) ||
            r->cache_bucket != state->root.slot ||
            r->cache_anchor != state->root.generation ||
            !lsf_device_record(&factory.pool, state->owner, *ticket, LSF_DEVICE_PCI))
            return NULL;
        return r;
    }
    return NULL;
}

static struct lsf_prepaid_view *lsf_stream_bind_pci_locked(
    struct lsf_stream_rx_state *state, const struct pci_dev *pci,
    struct lsf_prepaid_ticket *ticket)
{
    return lsf_stream_pci_record_locked(state, pci, ticket, 0);
}

static int lsf_stream_bind_current_locked(struct lsf_stream_rx_state *state)
{
    lockdep_assert_held(&pool_lock);
    return lsf_stream_constructor_current_locked(state) && state->bind_active &&
        state->bind_task == current && state->bind_attempted &&
        factory.device->bootstrap_state == LSF_FACTORY_BOOTSTRAP_READY &&
        !factory.device->bootstrap_busy && !factory.device->bootstrap_error &&
        factory.device->bootstrap_expires_ns &&
        ktime_get_ns() < factory.device->bootstrap_expires_ns;
}

int lsf_factory_stream_bind_selected(const struct pci_dev *pci)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_ticket ticket;
    unsigned long flags;
    int result = 0;
    if (!lsf_factory_selected_consumer()) return 0;
    spin_lock_irqsave(&pool_lock, flags);
    if (lsf_stream_rx_address_locked(pci)) {
        state = lsf_stream_rx_current_locked();
        result = lsf_stream_pci_record_locked(state, pci, &ticket, 1) ? 1 : -EOPNOTSUPP;
        if (result < 0) {
            factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1);
        }
    }
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

/* At actual pci_bus_add_device, AFTER native resource assignment. The source
 * wrapper retains its original administrative/attach order; missing allocating
 * ports remain pre-effect refusals, not successful device registration. */
int lsf_factory_stream_bind_begin(struct pci_dev *pci,
    struct lsf_stream_bind_reference *reference)
{
    struct lsf_factory_device_firmware *firmware;
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_ticket ticket;
    unsigned long flags;
    int result;
    if (!reference) return -EINVAL;
    memset(reference, 0, sizeof(*reference));
    result = lsf_factory_stream_bind_selected(pci);
    if (result <= 0) return result;
    mutex_lock(&factory_lock);
    spin_lock_irqsave(&pool_lock, flags);
    result = -EOPNOTSUPP;
    state = lsf_stream_rx_current_locked();
    if (!state || !lsf_stream_bind_pci_locked(state, pci, &ticket) ||
        state->closing || state->stopped || state->bind_attempted ||
        state->bind_active || state->bind_task ||
        (state->pci && state->pci != pci) || state->virtio ||
        factory.device->constructor_active || factory.device->constructor_task ||
        factory.device->bootstrap_state != LSF_FACTORY_BOOTSTRAP_READY ||
        factory.device->bootstrap_busy || factory.device->bootstrap_error ||
        !factory.device->bootstrap_expires_ns ||
        ktime_get_ns() >= factory.device->bootstrap_expires_ns ||
        !lsf_factory_device_core_actor() ||
        !(firmware = lsf_factory_device_firmware_for_pci(pci, ticket)) ||
        !firmware->core_initialized || firmware->revoked || firmware->retirement ||
        firmware->queued || firmware->returned || firmware->core_tail_active ||
        firmware->core_tail_complete || !device_is_registered(&pci->dev) ||
        pci->driver || pci->dev.driver || pci->match_driver || pci_dev_is_added(pci) ||
        state->device_borrows == UINT_MAX)
        goto out;
    /* This one-shot phase is recorded before any native bind effect. The state
     * fields are inside the actual sizeof(state) reserved before the PCI birth. */
    state->bind_attempted = 1;
    ++state->device_borrows;
    if (!kobject_get_unless_zero(&pci->dev.kobj)) {
        /* The SAME counted bank loan deliberately remains on unknown kref. */
        factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1);
        goto out;
    }
    state->pci = pci;
    state->bind_active = 1;
    state->bind_task = current;
    factory.device->constructor_active = 1;
    factory.device->constructor_task = current;
    *reference = (struct lsf_stream_bind_reference){state, pci, current,
        state->owner.generation, state->root.generation, ticket.generation,
        state->owner.slot, state->root.slot, ticket.slot, 1};
    result = 1;
out:
    spin_unlock_irqrestore(&pool_lock, flags);
    /* The original counted bank loan and positive PCI reference, not a held
     * private mutex, retain the graph across native callbacks. Every typed
     * birth still rechecks current/task/deadline under the original pool lock. */
    mutex_unlock(&factory_lock);
    return result;
}

/* Native caller has completed its original synchronous bind/error tail. Clear
 * the matching borrowed task BEFORE any poison-sensitive live lookup, then
 * unlock before native puts. Actual bank custody outlives all those callbacks. */
void lsf_factory_stream_bind_end(struct lsf_stream_bind_reference *reference, int bound)
{
    struct lsf_stream_rx_state *state;
    unsigned long flags;
    struct lsf_prepaid_ticket pci_ticket, vp_ticket;
    int pair, exact, live, drivers_bound;
    if (!reference || reference->active != 1 || reference->task != current) return;
    mutex_lock(&factory_lock);
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_netdev_core_borrow_state_locked();
    pair = state && state == reference->state && state->bind_active &&
        state->bind_task == current && state->pci == reference->pci;
    exact = pair &&
        state->owner.slot == reference->owner_slot &&
        state->owner.generation == reference->owner_generation &&
        state->root.slot == reference->root_slot &&
        state->root.generation == reference->root_generation;
    if (!exact) {
        /* Revoke only the matching synchronous task/object pair even if its
         * later generation checks fail. Retained lookup grants no release. */
        if (pair) {
            state->bind_task = NULL;
            state->bind_active = 0;
            if (factory.device->constructor_task == current)
                factory.device->constructor_task = NULL;
        }
        factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1);
        spin_unlock_irqrestore(&pool_lock, flags);
        /* This source-owned entry acquired this mutex on the same current
         * stack. Unlocking it neither returns the unknown PCI nor bank loan. */
        mutex_unlock(&factory_lock);
        if (pair) lsf_factory_device_firmware_constructor_leave();
        return;
    }
    /* Matching retained ownership lends only revocation here. A poisoned
     * live lookup or broken operation counter must not let current escape. */
    live = state->device_borrows && factory.device->constructor_active &&
        factory.device->constructor_task == current &&
        lsf_stream_bind_pci_locked(state, reference->pci, &pci_ticket) &&
        pci_ticket.slot == reference->pci_slot &&
        pci_ticket.generation == reference->pci_generation;
    /* device_add/PCI probe can succeed even when the child driver's probe
     * failed. Only the actual matched synchronous virtnet instance suffices
     * for this constructor history; a paid-but-unbound VP is not ready. */
    drivers_bound = live && bound == 1 && state->virtio &&
        lsf_stream_vp_record_locked(state, state->virtio, &vp_ticket) &&
        lsf_prepaid_stream_pci_driver_known(state->pci->driver) &&
        lsf_prepaid_stream_pci_device_driver_known(state->pci->dev.driver) &&
        lsf_prepaid_stream_virtio_driver_known(state->virtio->dev.driver);
    if (factory.device->constructor_task == current)
        factory.device->constructor_task = NULL;
    state->bind_task = NULL;
    state->bind_active = 0;
    state->bind_complete = drivers_bound && !factory.pool.poisoned &&
        !READ_ONCE(factory.uncertain) && !factory.pool.stopped &&
        factory.device->bootstrap_state == LSF_FACTORY_BOOTSTRAP_READY &&
        !factory.device->bootstrap_busy && !factory.device->bootstrap_error &&
        factory.device->bootstrap_expires_ns &&
        ktime_get_ns() < factory.device->bootstrap_expires_ns;
    state->bind_error = state->bind_complete ? 0u :
        (bound < 0 ? 0u - (unsigned int)bound : EOPNOTSUPP);
    if (!live) {
        factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1);
    }
    spin_unlock_irqrestore(&pool_lock, flags);
    mutex_unlock(&factory_lock);
    lsf_factory_device_firmware_constructor_leave();
    if (!live) return; /* Exact native/bank owners remain; no refund on error. */
    put_device(&reference->pci->dev);
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_netdev_core_borrow_state_locked();
    if (!state || state != reference->state ||
        state->owner.slot != reference->owner_slot ||
        state->owner.generation != reference->owner_generation ||
        state->root.slot != reference->root_slot ||
        state->root.generation != reference->root_generation ||
        !state->device_borrows) {
        factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1);
    } else {
        --state->device_borrows;
        lsf_factory_stream_root_notify_locked(&factory.pool);
    }
    spin_unlock_irqrestore(&pool_lock, flags);
    memset(reference, 0, sizeof(*reference));
}

int lsf_factory_stream_probe_current(const struct pci_dev *pci)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_ticket ticket;
    unsigned long flags;
    int result = lsf_factory_stream_bind_selected(pci);
    if (result <= 0) return result;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    result = lsf_stream_bind_pci_locked(state, pci, &ticket) &&
        lsf_stream_bind_current_locked(state) && state->pci == pci ? 1 : -EOPNOTSUPP;
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

/* This locates ONLY a prior actual VP birth. vdev is the first real field of
 * struct virtio_pci_device, checked by the allocating TU's geometry producer. */
static struct lsf_prepaid_view *lsf_stream_vp_record_locked(
    struct lsf_stream_rx_state *state, const void *address,
    struct lsf_prepaid_ticket *ticket)
{
    struct lsf_prepaid_view *r;
    struct lsf_prepaid_ticket pci;
    unsigned long base, at = (unsigned long)address;
    unsigned int i;
    lockdep_assert_held(&pool_lock);
    if (!state || !ticket || !state->vp_extent || !state->pci ||
        !lsf_stream_bind_pci_locked(state, state->pci, &pci) ||
        !lsf_stream_rx_address_locked(address)) return NULL;
    base = (unsigned long)page_address(factory.pages);
    for (i = 1; i < LSF_ALLOCATION_SLOTS; ++i) {
        r = &factory.pool.records[i];
        if (r->offset != at - base || r->kind != LSF_DEVICE_VIRTIO) continue;
        *ticket = (struct lsf_prepaid_ticket){i, r->generation};
        if (r->bytes != state->vp_extent ||
            r->cache_bucket != pci.slot || r->cache_anchor != pci.generation ||
            !lsf_device_record(&factory.pool, state->owner, *ticket, LSF_DEVICE_VIRTIO))
            return NULL;
        return r;
    }
    return NULL;
}

/* Only the actual matched builtin instance may enter its original probe.
 * This does not reinterpret an unknown driver/container or lend its callback
 * authority. Both original device locks remain held by synchronous attach. */
int lsf_factory_stream_attach_current(const struct device *device,
    const struct device_driver *driver)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_ticket ticket;
    unsigned long flags;
    int result = 0;
    spin_lock_irqsave(&pool_lock, flags);
    if (!lsf_stream_rx_address_locked(device)) goto out;
    result = -EOPNOTSUPP;
    state = lsf_stream_rx_current_locked();
    if (!lsf_stream_bind_current_locked(state)) goto out;
    if (state->pci && device == &state->pci->dev &&
        lsf_stream_bind_pci_locked(state, state->pci, &ticket)) {
        if (lsf_prepaid_stream_pci_device_driver_known(driver)) result = 1;
    } else if (state->virtio && device == &state->virtio->dev &&
        lsf_stream_vp_record_locked(state, state->virtio, &ticket)) {
        if (lsf_prepaid_stream_virtio_driver_known(driver)) result = 1;
    }
out:
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

int lsf_factory_stream_attach_bus_current(const struct device *device)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_ticket ticket;
    unsigned long flags;
    int result = 0;
    spin_lock_irqsave(&pool_lock, flags);
    if (!lsf_stream_rx_address_locked(device)) goto out;
    result = -EOPNOTSUPP;
    state = lsf_stream_rx_current_locked();
    if (!lsf_stream_bind_current_locked(state)) goto out;
    /* The source-pinned bus objects are CONST. Authenticate their identities
     * before the native matcher can be called on any driver instance. */
    if (state->pci && device == &state->pci->dev &&
        lsf_stream_bind_pci_locked(state, state->pci, &ticket)) {
        if (lsf_prepaid_stream_pci_bus_known(device->bus)) result = 1;
    } else if (state->virtio && device == &state->virtio->dev &&
        lsf_stream_vp_record_locked(state, state->virtio, &ticket)) {
        if (lsf_prepaid_stream_virtio_bus_known(device->bus)) result = 1;
    }
out:
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

void *lsf_factory_stream_vp_allocate(struct pci_dev *pci, unsigned long actual_bytes)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_ticket parent, ticket;
    struct lsf_prepaid_view *record;
    unsigned long flags, bytes, alignment;
    u64 offset;
    void *result = NULL;
    if (lsf_prepaid_stream_vp_geometry(&bytes, &alignment) || !bytes ||
        bytes > ULONG_MAX - 63u || actual_bytes != bytes || !alignment ||
        alignment > 64u || (alignment & (alignment - 1u))) return NULL;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    if (!lsf_stream_bind_pci_locked(state, pci, &parent) ||
        !lsf_stream_bind_current_locked(state) || state->vp_attempted ||
        state->virtio || state->pci != pci) goto out;
    state->vp_attempted = 1; /* No ambient retry or later allocation adoption. */
    if (lsf_stream_constructor_allocate_locked(state, LSF_DEVICE_VIRTIO, parent,
        bytes, alignment, &ticket, &offset) != 1) goto out;
    state->vp_extent = (bytes + 63u) & ~63ul;
    record = &factory.pool.records[ticket.slot];
    /* Real child record/extent exists BEFORE this extra original parent ref. */
    if (!kobject_get_unless_zero(&pci->dev.kobj)) goto poison;
    record->security_cache_location = LSF_STREAM_VP_PARENT_HELD;
    record->security_cache_identity = 0;
    result = (char *)page_address(factory.pages) + offset;
    memset(result, 0, bytes);
    if (!lsf_device_publish(&factory.pool, state->owner, ticket, LSF_DEVICE_VIRTIO)) {
        result = NULL;
        goto poison;
    }
    state->virtio = result;
    goto out;
poison:
    factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1);
out:
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

/* Only original pre-register failure may return an uninitialized VP. After
 * device_initialize, the original release callback is merely a witness and
 * the entire object remains charged until its actual kobject epilogue. */
int lsf_factory_stream_vp_return_uninitialized(void *address)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_view *record;
    struct lsf_prepaid_ticket ticket;
    struct pci_dev *parent = NULL;
    unsigned long flags;
    int result = 0;
    spin_lock_irqsave(&pool_lock, flags);
    if (!lsf_stream_rx_address_locked(address)) goto out;
    result = -EOPNOTSUPP;
    state = lsf_stream_rx_current_locked();
    record = lsf_stream_vp_record_locked(state, address, &ticket);
    if (!record || !lsf_stream_bind_current_locked(state) ||
        record->deferred != LSF_PREPAID_PUBLISHED ||
        record->security_cache_location != LSF_STREAM_VP_PARENT_HELD ||
        record->security_cache_identity || state->virtio != address)
        goto poison;
    parent = (struct pci_dev *)state->pci;
    state->virtio = NULL; /* Clear aliases before the real typed view return. */
    if (!lsf_device_queue(&factory.pool, state->owner, ticket, LSF_DEVICE_VIRTIO) ||
        !lsf_device_finish(&factory.pool, state->owner, ticket, LSF_DEVICE_VIRTIO)) {
        parent = NULL; /* Failed return retains the original native reference. */
        goto poison;
    }
    record->security_cache_location = 0;
    state->vp_returned = ticket;
    state->vp_returned_address = address;
    result = 1;
    goto out;
poison:
    factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1);
out:
    spin_unlock_irqrestore(&pool_lock, flags);
    /* SAME bind bank loan is still held; no callback/drop under pool_lock. */
    if (parent) put_device(&parent->dev);
    return result;
}

int lsf_factory_stream_vp_release_seen(void *address)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_view *record;
    struct lsf_prepaid_ticket ticket;
    unsigned long flags;
    int result = 0;
    spin_lock_irqsave(&pool_lock, flags);
    if (!lsf_stream_rx_address_locked(address)) goto out;
    result = -EOPNOTSUPP;
    state = lsf_stream_rx_current_locked();
    record = lsf_stream_vp_record_locked(state, address, &ticket);
    if (!record || record->deferred != LSF_PREPAID_PUBLISHED ||
        record->security_cache_location != LSF_STREAM_VP_PARENT_HELD ||
        record->security_cache_identity !=
            (LSF_STREAM_VP_CORE_INITIALIZED | LSF_STREAM_VP_TAIL_ACTIVE) ||
        state->vp_tail_task != current ||
        state->vp_tail_object != &((struct virtio_device *)address)->dev.kobj)
        goto poison;
    record->security_cache_identity |= LSF_STREAM_VP_RELEASE_SEEN;
    if (!lsf_device_queue(&factory.pool, state->owner, ticket, LSF_DEVICE_VIRTIO))
        goto poison;
    result = 1; /* Not a return/refund; original kobject code still uses it. */
    goto out;
poison:
    factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1);
out:
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

/* A completed real kobject tail may still have charged kernfs/other children.
 * Pending is not an error and never returns the VP or its original PCI ref.
 * Called after the actual tail/barrier, including the existing Root collector. */
static int lsf_stream_vp_drain_completed(struct lsf_stream_rx_state *expected)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_view *record, *child;
    struct lsf_prepaid_ticket ticket;
    struct pci_dev *pci;
    unsigned long flags;
    unsigned int i;
    int result = 0;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    if (!state || state != expected) goto poison;
    if (!state->virtio) goto out; /* A genuine absent/pre-init-returned birth. */
    record = lsf_stream_vp_record_locked(state, state->virtio, &ticket);
    if (!record) goto poison;
    if (record->deferred != LSF_PREPAID_QUEUED ||
        !(record->security_cache_identity & LSF_STREAM_VP_TAIL_DONE)) goto out;
    if (record->security_cache_identity != (LSF_STREAM_VP_CORE_INITIALIZED |
        LSF_STREAM_VP_RELEASE_SEEN | LSF_STREAM_VP_TAIL_DONE) ||
        record->security_cache_location != LSF_STREAM_VP_PARENT_HELD ||
        state->vp_tail_task || state->vp_tail_object ||
        state->device_borrows == UINT_MAX) goto poison;
    for (i = 1; i < LSF_ALLOCATION_SLOTS; ++i) {
        child = &factory.pool.records[i];
        if (child->owner == state->owner.slot &&
            child->owner_generation == state->owner.generation &&
            child->cache_bucket == ticket.slot &&
            child->cache_anchor == ticket.generation &&
            child->phase != LSF_PREPAID_RETURNED) goto out;
    }
    ++state->device_borrows;
    pci = (struct pci_dev *)state->pci;
    record->security_cache_location = 0;
    if (!lsf_device_finish(&factory.pool, state->owner, ticket, LSF_DEVICE_VIRTIO)) {
        record->security_cache_location = LSF_STREAM_VP_PARENT_HELD;
        --state->device_borrows;
        goto poison;
    }
    state->virtio = NULL;
    state->vp_returned = ticket;
    state->vp_returned_address = (char *)page_address(factory.pages) + record->offset;
    spin_unlock_irqrestore(&pool_lock, flags);
    put_device(&pci->dev); /* SAME bank loan spans its complete native tail. */
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_netdev_core_borrow_state_locked();
    if (!state || state != expected || !state->device_borrows) goto poison;
    --state->device_borrows;
    lsf_factory_stream_root_notify_locked(&factory.pool);
    result = 1;
    goto out;
poison:
    factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1);
    result = -EIO;
out:
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

/* The last native put can complete the actual VP tail before its caller
 * returns. Only the saved SAME-record return history may replace the live
 * alias comparison; NULL alone is never a physical-retirement witness. */
int lsf_factory_stream_vp_device_matches_locked(struct lsf_stream_rx_state *state,
    const struct virtio_device *vdev)
{
    struct lsf_prepaid_view *record;
    unsigned long base;
    lockdep_assert_held(&pool_lock);
    if (!state || state != lsf_stream_rx_current_locked()) return 0;
    if (state->virtio == vdev) {
        struct lsf_prepaid_ticket ticket;
        return vdev && lsf_stream_vp_record_locked(state, vdev, &ticket);
    }
    if (state->virtio || !vdev || state->vp_returned_address != vdev ||
        !state->vp_returned.slot || state->vp_returned.slot >= LSF_ALLOCATION_SLOTS ||
        !state->vp_returned.generation || !factory.pages) return 0;
    base = (unsigned long)page_address(factory.pages);
    record = &factory.pool.records[state->vp_returned.slot];
    return record->phase == LSF_PREPAID_RETURNED && record->kind == LSF_DEVICE_VIRTIO &&
        record->generation == state->vp_returned.generation &&
        record->owner == state->owner.slot && record->owner_generation == state->owner.generation &&
        record->offset == (unsigned long)vdev - base && record->bytes == state->vp_extent &&
        record->security_cache_location == 0 &&
        record->security_cache_identity == (LSF_STREAM_VP_CORE_INITIALIZED |
            LSF_STREAM_VP_RELEASE_SEEN | LSF_STREAM_VP_TAIL_DONE);
}

/* Completed constructor history and live bank records, not a theorem about
 * unported PM/direct writers. In particular the bootstrap's absolute expiry
 * is not renewed or incorrectly imposed on every later normal socket lease.
 * The independent source-completeness/installation gate remains disabled. */
int lsf_factory_stream_bind_ready_locked(void)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_view *r;
    struct lsf_prepaid_ticket ticket;
    lockdep_assert_held(&factory_lock);
    lockdep_assert_held(&pool_lock);
    state = lsf_stream_rx_current_locked();
    if (!state || state->closing || state->stopped || state->bind_active ||
        state->bind_task || state->bind_complete != 1u || state->bind_error ||
        !state->pci || !state->virtio || factory.device->constructor_active ||
        factory.device->constructor_task || !lsf_stream_bind_pci_locked(state, state->pci, &ticket))
        return 0;
    r = lsf_stream_vp_record_locked(state, state->virtio, &ticket);
    return r && r->deferred == LSF_PREPAID_PUBLISHED &&
        r->security_cache_location == LSF_STREAM_VP_PARENT_HELD &&
        r->security_cache_identity == LSF_STREAM_VP_CORE_INITIALIZED;
}

