/* Exactly two native child classes: busy PCI resource and PAT interval.
 * Actual allocating TUs supply their real types; no table, new owner, caller
 * grant, renewed deadline or ordinary heap fallback is introduced. */
#include <net/lsf_stream_constructor_mapping_private.h>

static int lsf_stream_mapping_shape(unsigned int kind,
    unsigned long *bytes, unsigned long *alignment)
{
    int result;
    if (kind == LSF_STREAM_MAPPING_RESOURCE)
        result = lsf_prepaid_stream_resource_geometry(bytes, alignment);
    else if (kind == LSF_STREAM_MAPPING_PAT)
        result = lsf_prepaid_stream_pat_geometry(bytes, alignment);
    else return 0;
    return result == 1 && *bytes && *bytes <= ULONG_MAX - 63u &&
        *alignment && *alignment <= 64u && !(*alignment & (*alignment - 1u));
}

static struct lsf_prepaid_view *lsf_stream_mapping_raw_locked(const void *address,
    unsigned int kind, struct lsf_prepaid_ticket *ticket)
{
    unsigned long base, at = (unsigned long)address;
    unsigned int i;
    lockdep_assert_held(&pool_lock);
    if (!factory.pages || !factory.pool.initialized ||
        (kind != LSF_STREAM_MAPPING_RESOURCE && kind != LSF_STREAM_MAPPING_PAT)) return NULL;
    base = (unsigned long)page_address(factory.pages);
    if (at < base || at - base >= LSF_BACKING_BYTES) return NULL;
    for (i = 1; i < LSF_ALLOCATION_SLOTS; ++i) {
        struct lsf_prepaid_view *r = &factory.pool.records[i];
        if (r->kind != kind || r->offset != at - base) continue;
        *ticket = (struct lsf_prepaid_ticket){i, r->generation};
        return r;
    }
    return NULL;
}

int lsf_factory_stream_mapping_classify(const void *address, unsigned int kind)
{
    struct lsf_prepaid_ticket ticket;
    unsigned long flags;
    int result = 0;
    spin_lock_irqsave(&pool_lock, flags);
    if (lsf_stream_rx_address_locked(address))
        result = lsf_stream_mapping_raw_locked(address, kind, &ticket) ? 1 : -EOPNOTSUPP;
    spin_unlock_irqrestore(&pool_lock, flags);
    return result; /* Classification grants no access or return authority. */
}

static struct lsf_prepaid_view *lsf_stream_mapping_current_locked(
    struct lsf_stream_rx_state *state, const void *address, unsigned int kind,
    struct lsf_prepaid_ticket *ticket)
{
    struct lsf_prepaid_view *r, *pci;
    unsigned long bytes, alignment;
    lockdep_assert_held(&pool_lock);
    if (!state || state != lsf_stream_rx_current_locked() ||
        !lsf_stream_mapping_shape(kind, &bytes, &alignment)) return NULL;
    r = lsf_stream_mapping_raw_locked(address, kind, ticket);
    if (!r || lsf_device_record(&factory.pool, state->owner, *ticket, kind) != r ||
        r->deferred != LSF_PREPAID_PUBLISHED || r->bytes != ((bytes + 63u) & ~63ull) ||
        r->offset % alignment || !r->cache_bucket || r->cache_bucket >= LSF_ALLOCATION_SLOTS ||
        !r->cache_anchor || r->security_cache_identity) return NULL;
    pci = &factory.pool.records[r->cache_bucket];
    if (pci->phase != LSF_PREPAID_LIVE || pci->kind != LSF_DEVICE_PCI ||
        pci->generation != r->cache_anchor || pci->owner != state->owner.slot ||
        pci->owner_generation != state->owner.generation ||
        pci->cache_bucket != state->root.slot || pci->cache_anchor != state->root.generation)
        return NULL;
    return r; /* Only immutable original parent metadata, no retired PCI read. */
}

static int lsf_stream_mapping_cleanup_current_locked(struct lsf_stream_rx_state *state)
{
    lockdep_assert_held(&pool_lock);
    return state && state->device_borrows &&
        ((state->bind_active && state->bind_task == current) ||
         (state->closing && state->hardware_stopped && state->mapping_stop_task == current));
}

static int lsf_stream_mapping_bar_locked(struct lsf_stream_rx_state *state,
    struct pci_dev *pci, u64 start, u64 end, unsigned int memory_only)
{
    struct lsf_prepaid_ticket parent;
    unsigned int i;
    lockdep_assert_held(&pool_lock);
    if (start >= end || !lsf_stream_bind_current_locked(state) ||
        !lsf_stream_bind_pci_locked(state, pci, &parent)) return 0;
    /* This is called only from the actual synchronous private PCI probe,
     * under its original device lock; no arbitrary native pointer is adopted. */
    for (i = 0; i < PCI_STD_NUM_BARS; ++i) {
        unsigned long type = pci_resource_flags(pci, i) & IORESOURCE_TYPE_BITS;
        if ((type != IORESOURCE_MEM && type != IORESOURCE_IO) ||
            (memory_only && type != IORESOURCE_MEM)) continue;
        if (pci_resource_start(pci, i) <= start && pci_resource_end(pci, i) >= end - 1u)
            return 1;
    }
    return 0;
}

static int lsf_stream_mapping_reserved_locked(struct lsf_stream_rx_state *state,
    struct pci_dev *pci, u64 start, u64 end)
{
    struct lsf_prepaid_ticket parent, ticket;
    struct lsf_prepaid_view *r;
    unsigned long base;
    unsigned int i;
    lockdep_assert_held(&pool_lock);
    if (!lsf_stream_mapping_bar_locked(state, pci, start, end, 1) ||
        !lsf_stream_bind_pci_locked(state, pci, &parent)) return 0;
    base = (unsigned long)page_address(factory.pages);
    for (i = 1; i < LSF_ALLOCATION_SLOTS; ++i) {
        struct resource *resource;
        r = &factory.pool.records[i];
        if (r->kind != LSF_STREAM_MAPPING_RESOURCE || r->phase != LSF_PREPAID_LIVE ||
            r->cache_bucket != parent.slot || r->cache_anchor != parent.generation) continue;
        resource = (void *)(base + r->offset);
        if (lsf_stream_mapping_current_locked(state, resource, LSF_STREAM_MAPPING_RESOURCE, &ticket) != r ||
            r->security_cache_location != 1u) continue;
        if ((READ_ONCE(resource->flags) & (IORESOURCE_TYPE_BITS | IORESOURCE_BUSY)) ==
            (IORESOURCE_MEM | IORESOURCE_BUSY) && READ_ONCE(resource->start) <= start &&
            READ_ONCE(resource->end) >= end - 1u) return 1;
    }
    return 0;
}

int lsf_factory_stream_mapping_range(struct pci_dev *pci, u64 start, u64 end)
{
    struct lsf_stream_rx_state *state;
    unsigned long flags;
    int result;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    result = lsf_stream_mapping_reserved_locked(state, pci, start, end);
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

int lsf_factory_stream_mapping_parent(const struct pci_dev *pci,
    const void *address, unsigned int kind)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_view *r, *parent;
    struct lsf_prepaid_ticket ticket;
    unsigned long flags;
    int result = 0;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    r = lsf_stream_mapping_current_locked(state, address, kind, &ticket);
    if (r && state->pci == pci) {
        parent = &factory.pool.records[r->cache_bucket];
        result = pci == (void *)((char *)page_address(factory.pages) + parent->offset);
    }
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

void *lsf_factory_stream_mapping_allocate(struct pci_dev *pci, unsigned int kind,
    unsigned long bytes, unsigned long alignment, u64 start, u64 end)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_ticket parent, ticket;
    unsigned long flags, actual, actual_alignment;
    u64 offset;
    void *result = NULL;
    if (!lsf_stream_mapping_shape(kind, &actual, &actual_alignment) ||
        bytes != actual || alignment != actual_alignment) return NULL;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    if (!lsf_stream_bind_pci_locked(state, pci, &parent) ||
        !(kind == LSF_STREAM_MAPPING_RESOURCE ?
          lsf_stream_mapping_bar_locked(state, pci, start, end, 0) :
          lsf_stream_mapping_reserved_locked(state, pci, start, end))) goto out;
    if (lsf_stream_constructor_allocate_locked(state, kind, parent, bytes,
        alignment, &ticket, &offset) != 1) goto out;
    factory.pool.records[ticket.slot].security_cache_location = 0;
    factory.pool.records[ticket.slot].security_cache_identity = 0;
    result = (char *)page_address(factory.pages) + offset;
    memset(result, 0, bytes);
    if (!lsf_device_publish(&factory.pool, state->owner, ticket, kind)) {
        factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1); result = NULL;
    }
out:
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

static int lsf_stream_mapping_transition(const void *address, unsigned int kind,
    unsigned int from, unsigned int to)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_view *r;
    struct lsf_prepaid_ticket ticket;
    unsigned long flags;
    int result = lsf_factory_stream_mapping_classify(address, kind);
    if (result <= 0) return result;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    r = lsf_stream_mapping_current_locked(state, address, kind, &ticket);
    if (!r || r->security_cache_location != from ||
        !lsf_stream_mapping_cleanup_current_locked(state)) {
        factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1); result = -EOPNOTSUPP;
    } else {
        r->security_cache_location = to;
        result = 1;
    }
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

int lsf_factory_stream_mapping_linked(const void *address, unsigned int kind)
{
    return lsf_stream_mapping_transition(address, kind, 0u, 1u);
}

int lsf_factory_stream_mapping_can_unlink(const void *address, unsigned int kind)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_view *r;
    struct lsf_prepaid_ticket ticket;
    unsigned long flags;
    int result = lsf_factory_stream_mapping_classify(address, kind);
    if (result <= 0) return result;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    r = lsf_stream_mapping_current_locked(state, address, kind, &ticket);
    result = -EOPNOTSUPP;
    if (!r || r->security_cache_location != 1u) {
        factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1);
    } else if (lsf_stream_mapping_cleanup_current_locked(state)) result = 1;
    /* An authenticated but foreign unlink is refused BEFORE native effects.
     * That expected authority denial is not an uncertain Root mutation. */
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

int lsf_factory_stream_mapping_unlinked(const void *address, unsigned int kind)
{
    return lsf_stream_mapping_transition(address, kind, 1u, 2u);
}

int lsf_factory_stream_mapping_return(const void *address, unsigned int kind)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_view *r;
    struct lsf_prepaid_ticket ticket;
    unsigned long flags;
    int result = lsf_factory_stream_mapping_classify(address, kind);
    if (result <= 0) return result;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    r = lsf_stream_mapping_current_locked(state, address, kind, &ticket);
    if (!r || !((r->security_cache_location == 0u &&
                 lsf_stream_mapping_cleanup_current_locked(state)) ||
                r->security_cache_location == 2u) ||
        !lsf_device_queue(&factory.pool, state->owner, ticket, kind) ||
        !lsf_device_finish(&factory.pool, state->owner, ticket, kind)) {
        factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1); result = -EOPNOTSUPP;
    } else result = 1;
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

int lsf_factory_stream_mapping_stop_enter(struct lsf_stream_rx_state *expected,
    const struct pci_dev *pci)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_ticket ticket;
    unsigned long flags;
    int result = -EOPNOTSUPP;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    if (state == expected && state && state->closing && state->hardware_stopped &&
        state->device_borrows && !state->mapping_stop_task && state->pci == pci &&
        lsf_stream_pci_record_locked(state, pci, &ticket, 1)) {
        state->mapping_stop_task = current;
        result = 1;
    }
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

int lsf_factory_stream_mapping_stop_leave(struct lsf_stream_rx_state *expected,
    const struct pci_dev *pci)
{
    struct lsf_stream_rx_state *state;
    unsigned long flags;
    int result = -EOPNOTSUPP;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_netdev_core_borrow_state_locked();
    if (state == expected && state && state->pci == pci && state->mapping_stop_task == current) {
        state->mapping_stop_task = NULL; /* Revocation before live/poison checks. */
        if (state == lsf_stream_rx_current_locked() && state->closing &&
            state->hardware_stopped && state->device_borrows) result = 1;
    }
    if (result != 1) {
        factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1);
    }
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

/* SPDX-License-Identifier: GPL-2.0-only */
/* Included after the actual PTE owner. Actual view metadata is a child of
 * that SAME Root leaf; a real positive PCI reference covers its native PCI
 * pointer through error/unmap and is put outside pool/factory locks. */
#include <net/lsf_stream_constructor_mmio_private.h>
static_assert((unsigned int)LSF_STREAM_MMIO_VIEW == (unsigned int)LSF_DEVICE_STREAM_MMIO_VIEW);

static int lsf_stream_mmio_task_locked(void)
{
    struct lsf_stream_rx_state *state;
    lockdep_assert_held(&pool_lock);
    state = lsf_stream_netdev_core_borrow_state_locked();
    /* Retained fields lend REFUSAL only on a poisoned/closed graph. A fresh
     * live original record/actor is still required for every positive path. */
    return state && ((state->bind_active && state->bind_task == current) ||
        state->mapping_stop_task == current);
}

int lsf_factory_stream_mmio_task(void)
{
    unsigned long flags;
    int result;
    if (!lsf_factory_selected_consumer()) return 0;
    spin_lock_irqsave(&pool_lock, flags);
    result = lsf_stream_mmio_task_locked();
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

int lsf_factory_stream_mmio_pci_selected(const struct pci_dev *pci)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_ticket ticket;
    unsigned long flags;
    int result = 0;
    if (!lsf_factory_selected_consumer()) return 0;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    if (lsf_stream_mmio_task_locked()) {
        result = state && pci && lsf_stream_bind_current_locked(state) &&
            lsf_stream_bind_pci_locked(state, pci, &ticket) ? 1 : -EOPNOTSUPP;
    } else if (pci && (lsf_stream_rx_address_locked(pci) ||
        lsf_stream_rx_address_locked(pci->dev.parent))) {
        result = -EOPNOTSUPP; /* Unknown/mixed/private ancestry never falls through. */
    }
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

static int lsf_stream_mmio_geometry(unsigned long *bytes, unsigned long *alignment,
    unsigned long *start, unsigned long *limit)
{
    return lsf_prepaid_stream_mmio_geometry(bytes, alignment, start, limit) == 1 &&
        *bytes && *bytes <= ULONG_MAX - 63u && *alignment && *alignment <= 64u &&
        !(*alignment & (*alignment - 1u)) && *start && *limit == PMD_SIZE;
}

static struct lsf_prepaid_view *lsf_stream_mmio_record_locked(
    struct lsf_stream_rx_state *state, const struct lsf_stream_mmio_view *view,
    struct lsf_prepaid_ticket *ticket)
{
    struct lsf_prepaid_view *r, *leaf;
    unsigned long at = (unsigned long)view, base;
    unsigned long bytes, alignment, start, limit, end;
    unsigned int i;
    struct lsf_prepaid_ticket pci;
    lockdep_assert_held(&pool_lock);
    if (!state || state != lsf_stream_rx_current_locked() ||
        state->owner.slot != LSF_DEVICE_OWNER_SLOT || !factory.pages ||
        !lsf_stream_mmio_geometry(&bytes, &alignment, &start, &limit)) return NULL;
    base = (unsigned long)page_address(factory.pages);
    if (at < base || at - base >= LSF_BACKING_BYTES) return NULL;
    for (i = 1; i < LSF_ALLOCATION_SLOTS; ++i) {
        r = &factory.pool.records[i];
        if (r->kind != LSF_STREAM_MMIO_VIEW || r->offset != at - base) continue;
        *ticket = (struct lsf_prepaid_ticket){i, r->generation};
        if (lsf_device_record(&factory.pool, state->owner, *ticket, LSF_STREAM_MMIO_VIEW) != r ||
            r->deferred != LSF_PREPAID_PUBLISHED || r->bytes != ((bytes + 63u) & ~63ull) ||
            r->offset % alignment || r->cache_bucket != state->vwindow_leaf_ticket.slot ||
            r->cache_anchor != state->vwindow_leaf_ticket.generation ||
            r->security_cache_identity || r->security_cache_location > 3u ||
            !(leaf = lsf_stream_pte_current_locked(state, state->vwindow_leaf)) ||
            leaf->security_cache_location != 1u ||
            !lsf_stream_pci_record_locked(state, state->pci, &pci, 1)) return NULL;
        /* Actual paid type and parent were proved BEFORE payload fields. */
        if (view->pci != state->pci || view->pci_slot != pci.slot ||
            view->pci_generation != pci.generation || view->pci_hold != 1 ||
            !view->bytes || !PAGE_ALIGNED(view->bytes) ||
            !PAGE_ALIGNED(view->physical_start) || !PAGE_ALIGNED(view->virtual_start) ||
            view->page_offset >= PAGE_SIZE || view->virtual_start < start ||
            check_add_overflow(view->virtual_start, view->bytes, &end) ||
            end - start > limit || view->returned_address != view->virtual_start + view->page_offset)
            return NULL;
        return r;
    }
    return NULL;
}

static int lsf_stream_mmio_authority_locked(struct lsf_stream_rx_state *state,
    const struct lsf_prepaid_view *r, unsigned int operation)
{
    lockdep_assert_held(&pool_lock);
    if (!state->device_borrows) return 0;
    if (operation == LSF_STREAM_MMIO_MAP)
        return r->security_cache_location == 0 && lsf_stream_bind_current_locked(state);
    if (!lsf_stream_mapping_cleanup_current_locked(state)) return 0;
    return (operation == LSF_STREAM_MMIO_UNMAP && r->security_cache_location == 1u) ||
        (operation == LSF_STREAM_MMIO_CANCEL && r->security_cache_location == 0u);
}

struct lsf_stream_mmio_view *lsf_factory_stream_mmio_allocate(struct pci_dev *pci,
    u64 physical, unsigned long size, unsigned long offset, pgprot_t prot, struct memtype *pat)
{
    struct lsf_stream_rx_state *state;
    struct lsf_stream_mmio_view *view = NULL;
    struct lsf_prepaid_view *leaf, *pat_record;
    struct lsf_prepaid_ticket parent, ticket, pat_ticket;
    unsigned long bytes, alignment, start, limit, flags, virtual, next;
    u64 end, at;
    if (!size || !PAGE_ALIGNED(size) || !PAGE_ALIGNED(physical) || offset >= PAGE_SIZE ||
        check_add_overflow(physical, (u64)size, &end) ||
        !lsf_stream_mmio_geometry(&bytes, &alignment, &start, &limit)) return NULL;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    if (!lsf_stream_bind_current_locked(state) || !state->device_borrows ||
        !lsf_stream_bind_pci_locked(state, pci, &parent) ||
        !(leaf = lsf_stream_pte_current_locked(state, state->vwindow_leaf)) ||
        leaf->security_cache_location != 1u ||
        !lsf_stream_mapping_reserved_locked(state, pci, physical, end) ||
        state->vwindow_live_views == UINT_MAX || state->vwindow_cursor > limit ||
        !PAGE_ALIGNED(state->vwindow_cursor) ||
        check_add_overflow((unsigned long)state->vwindow_cursor, size, &next) || next > limit ||
        check_add_overflow(start, (unsigned long)state->vwindow_cursor, &virtual)) goto out;
    if (pat) {
        pat_record = lsf_stream_mapping_current_locked(state, pat, LSF_STREAM_MAPPING_PAT, &pat_ticket);
        if (!pat_record || pat_record->security_cache_location != 1u ||
            pat_record->cache_bucket != parent.slot || pat_record->cache_anchor != parent.generation)
            goto out;
    }
    if (lsf_stream_constructor_allocate_locked(state, LSF_STREAM_MMIO_VIEW,
        state->vwindow_leaf_ticket, bytes, alignment, &ticket, &at) != 1) goto out;
    view = (void *)((char *)page_address(factory.pages) + at);
    memset(view, 0, bytes);
    /* Pay metadata BEFORE acquiring this genuine secondary native lifetime.
     * No parent-finalrelease cycle: actual PCI removal unmaps these views
     * before the retained original PCI references are put. */
    if (!kobject_get_unless_zero(&pci->dev.kobj)) {
        factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1); view = NULL;
        goto out;
    }
    *view = (struct lsf_stream_mmio_view){
        .pci=pci, .pat=pat, .virtual_start=virtual, .returned_address=virtual+offset,
        .bytes=size, .page_offset=offset, .physical_start=physical, .protection=prot,
        .pci_generation=parent.generation, .pci_slot=parent.slot, .pci_hold=1,
    };
    factory.pool.records[ticket.slot].security_cache_location = 0;
    factory.pool.records[ticket.slot].security_cache_identity = 0;
    state->vwindow_cursor = next;
    ++state->vwindow_live_views;
    if (!lsf_device_publish(&factory.pool, state->owner, ticket, LSF_STREAM_MMIO_VIEW)) {
        factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1); view = NULL;
        /* The exact paid record still contains its real PCI-reference owner. */
    }
out:
    spin_unlock_irqrestore(&pool_lock, flags);
    return view;
}

int lsf_factory_stream_mmio_owned(const struct lsf_stream_mmio_view *view, unsigned int operation)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_view *r;
    struct lsf_prepaid_ticket ticket;
    unsigned long flags;
    int result = -EOPNOTSUPP;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    r = lsf_stream_mmio_record_locked(state, view, &ticket);
    if (r && lsf_stream_mmio_authority_locked(state, r, operation)) result = 1;
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

int lsf_factory_stream_mmio_transition(struct lsf_stream_mmio_view *view,
    unsigned int from, unsigned int to)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_view *r;
    struct lsf_prepaid_ticket ticket;
    unsigned long flags;
    int result = -EOPNOTSUPP;
    unsigned int operation;
    if (from == 0 && to == 1) operation = LSF_STREAM_MMIO_MAP;
    else if (from == 1 && to == 2) operation = LSF_STREAM_MMIO_UNMAP;
    else if (from == 0 && to == 3) operation = LSF_STREAM_MMIO_CANCEL;
    else return -EINVAL;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    r = lsf_stream_mmio_record_locked(state, view, &ticket);
    if (r && r->security_cache_location == from &&
        lsf_stream_mmio_authority_locked(state, r, operation)) {
        r->security_cache_location = to; result = 1;
    } else {
        factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1);
    }
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

