}

int lsf_factory_stream_mmio_finish(struct lsf_stream_mmio_view *view)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_view *r, *pat;
    struct lsf_prepaid_ticket ticket, pat_ticket;
    struct pci_dev *held = NULL;
    unsigned int slot;
    u64 generation;
    unsigned long flags, pat_bytes, pat_alignment;
    int result = -EOPNOTSUPP;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    r = lsf_stream_mmio_record_locked(state, view, &ticket);
    if (!r || !state->vwindow_live_views || !lsf_stream_mapping_cleanup_current_locked(state) ||
        (r->security_cache_location != 3u && r->security_cache_location != 2u)) goto poison;
    if (view->pat) {
        pat = lsf_stream_mapping_raw_locked(view->pat, LSF_STREAM_MAPPING_PAT, &pat_ticket);
        if (!pat || !lsf_stream_mapping_shape(LSF_STREAM_MAPPING_PAT, &pat_bytes, &pat_alignment) ||
            pat->phase != LSF_PREPAID_RETURNED || pat->security_cache_location != 2u ||
            pat->security_cache_identity || pat->bytes != ((pat_bytes + 63u) & ~63ull) ||
            pat->offset % pat_alignment ||
            pat->cache_bucket != view->pci_slot || pat->cache_anchor != view->pci_generation ||
            pat->owner != state->owner.slot || pat->owner_generation != state->owner.generation)
            goto poison;
    }
    held = view->pci; slot = view->pci_slot; generation = view->pci_generation;
    view->pci = NULL; view->pci_hold = 0; view->pci_slot = 0; view->pci_generation = 0;
    view->pat = NULL; view->returned_address = 0;
    if (!lsf_device_queue(&factory.pool, state->owner, ticket, LSF_STREAM_MMIO_VIEW) ||
        !lsf_device_finish(&factory.pool, state->owner, ticket, LSF_STREAM_MMIO_VIEW)) {
        /* Preserve the actual secondary PCI-reference owner on uncertainty.
         * The mapping/PAT aliases stay invalidated, never re-admitted. */
        view->pci=held; view->pci_hold=1; view->pci_slot=slot; view->pci_generation=generation;
        held = NULL;
        goto poison;
    }
    --state->vwindow_live_views;
    result = 1;
    goto out;
poison:
    factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1);
out:
    spin_unlock_irqrestore(&pool_lock, flags);
    /* This is only the view's EXTRA reference, outside pool/factory locks.
     * The original bind/stop positive PCI ref and counted bank loan still
     * span this inner callback, so it cannot be final PCI destruction. The
     * PCI removal mutex may still be held by the original native caller. */
    if (held) pci_dev_put(held);
    return result;
}

static struct lsf_prepaid_view *lsf_stream_mmio_modern_locked(
    struct lsf_stream_rx_state *state, const void *mdev, unsigned int opening, const void *alias)
{
    struct lsf_prepaid_view *vp;
    struct lsf_prepaid_ticket pci, ticket;
    lockdep_assert_held(&pool_lock);
    if (!state || state != lsf_stream_rx_current_locked() || !state->device_borrows ||
        !lsf_stream_pci_record_locked(state, state->pci, &pci, 1) ||
        !(vp = lsf_stream_vp_record_locked(state, state->virtio, &ticket)) ||
        !lsf_prepaid_stream_mmio_mdev_layout(state->virtio, mdev, state->pci, alias, opening)) return NULL;
    if (opening)
        return vp->security_cache_identity == 0 && lsf_stream_bind_current_locked(state) ? vp : NULL;
    if (!lsf_stream_mapping_cleanup_current_locked(state)) return NULL;
    /* Pre-core probe rollback is BEFORE register_virtio_device, so no VQ
     * driver has run. Later registered cleanup needs the ACTUAL native
     * unregister return witness, not a guessed no-queue/NULL-field claim. */
    if (vp->security_cache_identity == 0 && state->bind_active && state->bind_task == current)
        return vp;
    return vp->security_cache_identity == LSF_STREAM_VP_CORE_INITIALIZED &&
        state->closing && state->hardware_stopped && state->mapping_stop_task == current &&
        state->vwindow_unregister_done ? vp : NULL;
}

int lsf_factory_stream_mmio_modern_selected(const void *mdev, unsigned int opening)
{
    struct lsf_stream_rx_state *state;
    const struct pci_dev *outside;
    unsigned long flags;
    int result = 0;
    if (opening > 1u) return -EINVAL;
    if (!lsf_factory_selected_consumer()) return 0;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    if (lsf_stream_mmio_task_locked() || lsf_stream_rx_address_locked(mdev)) {
        /* Exact VP extent/layout BEFORE any private mdev payload is read. */
        result = lsf_stream_mmio_modern_locked(state, mdev, opening, NULL) ? 1 : -EOPNOTSUPP;
    } else if (mdev) {
        /* The ordinary public C caller supplies a valid native mdev. This
         * outside-only read lends REFUSAL on mixed ancestry, never a grant. */
        outside = lsf_prepaid_stream_mmio_outside_mdev_pci(mdev);
        if (outside && (lsf_stream_rx_address_locked(outside) ||
            lsf_stream_rx_address_locked(outside->dev.parent))) result = -EOPNOTSUPP;
    }
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

