int lsf_factory_stream_mmio_take_alias(const void *mdev, void *alias, void __iomem **result)
{
    struct lsf_stream_rx_state *state;
    struct lsf_stream_mmio_view *view;
    struct lsf_prepaid_view *r;
    struct lsf_prepaid_ticket ticket;
    void __iomem *address;
    unsigned long flags, base;
    unsigned int i;
    int found = -EOPNOTSUPP;
    if (!result) return -EINVAL;
