    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    if (!lsf_stream_mmio_modern_locked(state, mdev, 0u, alias)) goto out;
    memcpy(&address, alias, sizeof(address));
    if (!address) { found = 1; goto out; } /* Local no-op, NOT Root/free evidence. */
    base = (unsigned long)page_address(factory.pages);
    for (i = 1; i < LSF_ALLOCATION_SLOTS; ++i) {
        r = &factory.pool.records[i];
        if (r->kind != LSF_STREAM_MMIO_VIEW || r->phase != LSF_PREPAID_LIVE ||
            r->owner != state->owner.slot || r->owner_generation != state->owner.generation) continue;
        view = (void *)(base + r->offset);
        r = lsf_stream_mmio_record_locked(state, view, &ticket);
        if (!r || view->returned_address != (unsigned long __force)address ||
            !lsf_stream_mmio_authority_locked(state, r, LSF_STREAM_MMIO_UNMAP)) continue;
        /* Real typed VP/mdev/field-address and mapped view proved before
         * alias invalidation. Unregister completion/early rollback proved
         * all actual borrowers gone. Unknown aliases remain untouched. */
        memset(alias, 0, sizeof(address));
        *result = address;
        found = 1;
        break;
    }
