    }
    if (lsf_stream_constructor_allocate_locked(state, LSF_DEVICE_STREAM_PROC,
        parent, actual, alignment, &ticket, &offset) != 1) goto out;
    result = (char *)page_address(factory.pages) + offset;
    memset(result, 0, actual);
    if (!lsf_device_publish(&factory.pool, state->owner, ticket, LSF_DEVICE_STREAM_PROC)) {
        factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1); result = NULL;
    }
out:
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

/* Only metadata witnessing ALREADY performed native insertion/rundown. No
 * late allocation, renewed actor/deadline or raw PCI payload read is allowed. */
static int lsf_stream_proc_witness(const void *address, unsigned int witness)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_view *r;
    struct lsf_prepaid_ticket ticket;
    unsigned long flags;
    int result = lsf_factory_stream_proc_classify(address);
    if (result <= 0) return result;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    r = lsf_stream_proc_current_locked(state, address, &ticket);
    if (!r || r->security_cache_location ||
        (witness == LSF_STREAM_PROC_REGISTERED &&
         (r->security_cache_identity || !state->bind_active || state->bind_task != current)) ||
        (witness == LSF_STREAM_PROC_RUNDOWN &&
         r->security_cache_identity != LSF_STREAM_PROC_REGISTERED)) {
        factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1);
        result = -EOPNOTSUPP;
    } else {
        r->security_cache_identity |= witness;
        result = 1;
    }
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

int lsf_factory_stream_proc_registered(const void *address)
{
    return lsf_stream_proc_witness(address, LSF_STREAM_PROC_REGISTERED);
}

int lsf_factory_stream_proc_rundown(const void *address)
{
    return lsf_stream_proc_witness(address, LSF_STREAM_PROC_RUNDOWN);
}

/* Called at the native pde_free boundary: either the exact failed unpublished
 * constructor, or actual final pde_put AFTER native active/opener rundown.
 * The original proc_free_inum already ran. No PDE read follows this return. */
int lsf_factory_stream_proc_return(const void *address)
{
    struct lsf_stream_rx_state *state, *borrow;
    struct lsf_prepaid_view *r;
    struct lsf_prepaid_ticket ticket, pci;
    struct lsf_prepaid_key owner;
    unsigned long flags;
    int result = lsf_factory_stream_proc_classify(address);
    if (result <= 0) return result;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    r = lsf_stream_proc_current_locked(state, address, &ticket);
    if (!r || r->security_cache_location || state->device_borrows == UINT_MAX ||
        !((r->security_cache_identity == 0 && state->bind_active && state->bind_task == current) ||
          r->security_cache_identity == (LSF_STREAM_PROC_REGISTERED | LSF_STREAM_PROC_RUNDOWN)))
        goto poison;
    ++state->device_borrows;
    owner = state->owner;
    pci = (struct lsf_prepaid_ticket){r->cache_bucket, r->cache_anchor};
    if (!lsf_device_queue(&factory.pool, owner, ticket, LSF_DEVICE_STREAM_PROC) ||
        !lsf_device_finish(&factory.pool, owner, ticket, LSF_DEVICE_STREAM_PROC)) goto poison;
    borrow = state;
    spin_unlock_irqrestore(&pool_lock, flags);
    /* Re-evaluate the ORIGINAL PCI continuation after this real child return;
     * no native destructor is called under pool_lock or invented here. */
    lsf_factory_device_firmware_schedule(owner, pci);
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_netdev_core_borrow_state_locked();
    if (!state || state != borrow || !state->device_borrows) goto poison;
    --state->device_borrows;
    lsf_factory_stream_root_notify_locked(&factory.pool);
    result = 1;
    goto out;
poison:
    factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1);
    result = -EOPNOTSUPP; /* Original records/bank and any unknown loan remain. */
out:
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

