/* Actual Root-bank leaf owner. The static upper pages retain their separate
 * original bootstrap owner. This file must follow the constructor/mapping
 * helpers and precede the real synchronous bind/stop callers. */
#include <net/lsf_stream_constructor_pte_private.h>

static struct lsf_prepaid_view *lsf_stream_pte_current_locked(
    struct lsf_stream_rx_state *state, const void *address)
{
    struct lsf_prepaid_view *r;
    unsigned long base;
    lockdep_assert_held(&pool_lock);
    if (!state || state != lsf_stream_rx_current_locked() ||
        state->owner.slot != LSF_DEVICE_OWNER_SLOT || !factory.pages ||
        state->vwindow_leaf != address || !state->vwindow_leaf_ticket.slot ||
        state->vwindow_leaf_ticket.slot >= LSF_ALLOCATION_SLOTS) return NULL;
    r = lsf_device_record(&factory.pool, state->owner,
        state->vwindow_leaf_ticket, LSF_STREAM_PTE_LEAF);
    base = (unsigned long)page_address(factory.pages);
    if (!r || r->deferred != LSF_PREPAID_PUBLISHED || r->bytes != PAGE_SIZE ||
        r->offset % PAGE_SIZE || address != (void *)(base + r->offset) ||
        r->cache_bucket != state->root.slot || r->cache_anchor != state->root.generation ||
        r->security_cache_identity) return NULL;
    return r;
}

static int lsf_stream_pte_authority_locked(struct lsf_stream_rx_state *state,
    struct lsf_prepaid_view *r, unsigned int operation)
{
    unsigned int i;
    lockdep_assert_held(&pool_lock);
    if (!state->device_borrows) return 0;
    if (operation == LSF_STREAM_PTE_INSTALL)
        return r->security_cache_location == 0 && lsf_stream_bind_current_locked(state);
    /* Actual mapping_stop_task is lent only after the ORIGINAL all-four-slot
     * retired/history check and hardware quiesce. Stopped+closing prevent new
     * births, and the original counted bank/device loan remains held. */
    if (!state->closing || !state->hardware_stopped || !factory.pool.stopped ||
        !state->device_borrows || state->mapping_stop_task != current ||
        state->vwindow_live_views) return 0;
    /* The original record array, not the summary count, is authoritative for
     * every actual descendant. Queued/unknown child tails still remain LIVE. */
    for (i = 1; i < LSF_ALLOCATION_SLOTS; ++i) {
        struct lsf_prepaid_view *child = &factory.pool.records[i];
        if (child->phase == LSF_PREPAID_LIVE && child->owner == state->owner.slot &&
            child->owner_generation == state->owner.generation &&
            child->cache_bucket == state->vwindow_leaf_ticket.slot &&
            child->cache_anchor == state->vwindow_leaf_ticket.generation) return 0;
    }
    return (operation == LSF_STREAM_PTE_UNLINK && r->security_cache_location == 1u) ||
        (operation == LSF_STREAM_PTE_FLUSHED && r->security_cache_location == 2u);
}

int lsf_factory_stream_pte_owned(const void *address, unsigned int operation)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_view *r;
    unsigned long flags;
    int result = -EOPNOTSUPP;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    r = lsf_stream_pte_current_locked(state, address);
    if (r && lsf_stream_pte_authority_locked(state, r, operation)) result = 1;
    spin_unlock_irqrestore(&pool_lock, flags);
    return result; /* Proves exact record before the architecture reads it. */
}

int lsf_factory_stream_pte_transition(const void *address, unsigned int from,
    unsigned int to)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_view *r;
    unsigned long flags;
    unsigned int operation;
    int result = -EOPNOTSUPP;
    if (from == 0 && to == 1) operation = LSF_STREAM_PTE_INSTALL;
    else if (from == 1 && to == 2) operation = LSF_STREAM_PTE_UNLINK;
    else if (from == 2 && to == 3) operation = LSF_STREAM_PTE_FLUSHED;
    else return -EINVAL;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    r = lsf_stream_pte_current_locked(state, address);
    if (r && r->security_cache_location == from &&
        lsf_stream_pte_authority_locked(state, r, operation)) {
        r->security_cache_location = to;
        result = 1;
    } else {
        factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1);
    }
    spin_unlock_irqrestore(&pool_lock, flags);
    return result; /* Failed AFTER-effect witnesses retain SAME bank. */
}

int lsf_factory_stream_pte_prepare(struct pci_dev *pci)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_ticket parent, ticket;
    unsigned long flags;
    u64 offset;
    void *leaf = NULL;
    int failure = -EOPNOTSUPP;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    if (!lsf_stream_bind_current_locked(state) ||
        !lsf_stream_bind_pci_locked(state, pci, &parent) || state->vwindow_leaf ||
        state->vwindow_leaf_ticket.slot || state->vwindow_leaf_ticket.generation ||
        state->vwindow_live_views || state->owner.slot != LSF_DEVICE_OWNER_SLOT)
        goto out;
    /* The original aligned allocator pays actual cursor padding, extent and
     * generation BEFORE a page address is used. Do not relax the generic
     * typed constructor's64-byte alignment contract or allocate a new page. */
    if (!lsf_device_allocate_stream_aligned(&factory.pool, state->owner,
        PAGE_SIZE, LSF_STREAM_PTE_LEAF, state->root, &ticket, PAGE_SIZE, &offset)) {
        failure = -ENOBUFS;
        goto out;
    }
    leaf = (char *)page_address(factory.pages) + offset;
    memset(leaf, 0, PAGE_SIZE);
    factory.pool.records[ticket.slot].security_cache_location = 0;
    factory.pool.records[ticket.slot].security_cache_identity = 0;
    state->vwindow_leaf_ticket = ticket;
    state->vwindow_leaf = leaf;
    if (!lsf_device_publish(&factory.pool, state->owner, ticket, LSF_STREAM_PTE_LEAF)) {
        factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1); leaf = NULL;
        failure = -EIO;
    }
out:
    spin_unlock_irqrestore(&pool_lock, flags);
    if (!leaf) return failure;
    /* Original bind loan/positive PCI reference spans the real page-table
     * call. No native operation occurs under the metadata pool lock. */
    return lsf_prepaid_stream_pte_install(leaf);
}

int lsf_factory_stream_pte_retire(struct pci_dev *pci)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_view *r;
    struct lsf_prepaid_ticket ticket;
    unsigned long flags;
    void *leaf;
    int result;
    mutex_lock(&factory_lock);
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    leaf = state && state->pci == pci ? state->vwindow_leaf : NULL;
    r = leaf ? lsf_stream_pte_current_locked(state, leaf) : NULL;
    if (!r || !lsf_stream_contexts_retired_locked() ||
        !lsf_stream_pte_authority_locked(state, r, LSF_STREAM_PTE_UNLINK)) {
        spin_unlock_irqrestore(&pool_lock, flags);
        mutex_unlock(&factory_lock);
        return -EOPNOTSUPP;
    }
    spin_unlock_irqrestore(&pool_lock, flags);
    mutex_unlock(&factory_lock);
    result = lsf_prepaid_stream_pte_detach(leaf);
    if (result != 1) return result;
    mutex_lock(&factory_lock);
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    r = lsf_stream_pte_current_locked(state, leaf);
    if (!r || r->security_cache_location != 3u || state->vwindow_live_views ||
        !lsf_stream_contexts_retired_locked()) goto poison;
