     * record return. The whole physical backing remains Root-owned until
     * all original final-bank/device/IRQ/RCU fences also pass. */
    state->vwindow_leaf = NULL;
    state->vwindow_leaf_ticket = (struct lsf_prepaid_ticket){0};
    if (!lsf_device_queue(&factory.pool, state->owner, ticket, LSF_STREAM_PTE_LEAF) ||
        !lsf_device_finish(&factory.pool, state->owner, ticket, LSF_STREAM_PTE_LEAF)) goto poison;
    spin_unlock_irqrestore(&pool_lock, flags);
    mutex_unlock(&factory_lock);
    return 1;
poison:
    factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1);
    spin_unlock_irqrestore(&pool_lock, flags);
    mutex_unlock(&factory_lock);
    return -EOPNOTSUPP;
