#include <net/lsf_stream_constructor_private.h>

static struct lsf_prepaid_view *lsf_stream_virtio_core_parent_locked(
    struct lsf_stream_rx_state *state, const void *address, unsigned int kobject,
    struct lsf_prepaid_ticket *ticket, struct virtio_device **dev)
{
    unsigned long displacement = offsetof(struct virtio_device, dev), base, value;
    if (kobject) displacement += offsetof(struct device, kobj);
    lockdep_assert_held(&pool_lock);
    if (!lsf_stream_rx_address_locked(address)) return NULL;
    base = (unsigned long)page_address(factory.pages); value = (unsigned long)address;
    if (value - base < displacement) return NULL;
    *dev = (void *)(value - displacement);
    return lsf_stream_vp_record_locked(state, *dev, ticket);
}

/* 0 is not a VIRTIO root; existing PCI/outside dispatch remains authoritative.
 * A matching VIRTIO birth must authenticate before any object dereference. */
int lsf_factory_stream_virtio_core_classify(const void *address, unsigned int kobject)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_ticket ticket;
    struct virtio_device *dev;
    unsigned long flags, base, at = (unsigned long)address;
    unsigned long displacement = offsetof(struct virtio_device, dev);
    unsigned int i;
    int result = 0;
    if (kobject > 1u) return -EOPNOTSUPP;
    if (kobject) displacement += offsetof(struct device, kobj);
    spin_lock_irqsave(&pool_lock, flags);
    if (!lsf_stream_rx_address_locked(address)) goto out;
    base = (unsigned long)page_address(factory.pages);
    if (at - base < displacement) goto out;
    for (i = 1; i < LSF_ALLOCATION_SLOTS; ++i) {
        const struct lsf_prepaid_view *r = &factory.pool.records[i];
        if (r->kind != LSF_DEVICE_VIRTIO || r->offset != at - base - displacement) continue;
        result = -EOPNOTSUPP;
        state = lsf_stream_rx_current_locked();
        if (lsf_stream_virtio_core_parent_locked(state, address, kobject, &ticket, &dev)) result = 1;
        break;
    }
out:
    if (result < 0) { factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1); }
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

static int lsf_stream_virtio_core_shape(unsigned long *bytes, unsigned long *alignment)
{
    return !lsf_prepaid_stream_netdev_core_geometry(bytes, alignment) && *bytes &&
