    state = lsf_stream_rx_current_locked();
    r = lsf_stream_virtio_core_parent_locked(state, address, 1, &parent, &dev);
    if (state != borrow || !r || r->deferred != LSF_PREPAID_QUEUED ||
        r->security_cache_identity != (LSF_STREAM_VP_CORE_INITIALIZED | LSF_STREAM_VP_RELEASE_SEEN |
                                       LSF_STREAM_VP_TAIL_ACTIVE)) goto poison;
    child = lsf_stream_virtio_core_child_locked(state, parent, &ticket);
    if (factory.pool.poisoned || READ_ONCE(factory.uncertain) ||
        (child && child->phase != LSF_PREPAID_RETURNED)) goto poison;
    /* Original release, cached-name free and parent kobject_put all returned.
     * No payload dereference follows; the queued whole VIRTIO still retains
     * its original positive VIRTIO reference until stop drains its children. */
    r->security_cache_identity &= ~LSF_STREAM_VP_TAIL_ACTIVE;
    r->security_cache_identity |= LSF_STREAM_VP_TAIL_DONE;
    result = 1; goto out;
poison:
    factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1);
out:
    spin_unlock_irqrestore(&pool_lock, flags);
    if (result == 1) {
        (void)lsf_stream_vp_drain_completed(borrow);
        spin_lock_irqsave(&pool_lock, flags);
        state = lsf_stream_netdev_core_borrow_state_locked();
        if (state != borrow || !state || !state->device_borrows) {
            factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1);
            result = -EIO; /* Retain unknown original bank owner. */
        } else {
            --state->device_borrows;
            lsf_factory_stream_root_notify_locked(&factory.pool);
        }
        spin_unlock_irqrestore(&pool_lock, flags);
    }
    return result;
}

int lsf_factory_stream_virtio_core_name(struct virtio_device *dev)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_view *r;
    struct lsf_prepaid_ticket parent, ticket;
    unsigned long flags;
    unsigned int i;
    u64 offset;
    char name[sizeof("virtio") + 10u], *copy;
    int length, result = -EOPNOTSUPP;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    r = lsf_stream_vp_record_locked(state, dev, &parent);
    if (!r || r->deferred != LSF_PREPAID_PUBLISHED ||
        r->security_cache_identity != LSF_STREAM_VP_CORE_INITIALIZED ||
        dev->dev.kobj.name || dev->index < 0 ||
        !lsf_stream_bind_current_locked(state)) goto out;
    length = snprintf(name, sizeof(name), "virtio%u", (unsigned int)dev->index);
    if (length <= 0 || length >= sizeof(name)) goto out;
    for (i = 1; i < LSF_ALLOCATION_SLOTS; ++i) {
        r = &factory.pool.records[i];
        if (r->kind == LSF_DEVICE_VIRTIO_CORE_NAME && r->owner == state->owner.slot &&
            r->owner_generation == state->owner.generation && r->cache_bucket == parent.slot &&
            r->cache_anchor == parent.generation && r->phase != LSF_PREPAID_EMPTY) goto out;
    }
    result = lsf_stream_constructor_allocate_locked(state, LSF_DEVICE_VIRTIO_CORE_NAME,
        parent, sizeof(name), __alignof__(name), &ticket, &offset);
    if (result != 1) goto out;
    copy = (char *)page_address(factory.pages) + offset;
    memset(copy, 0, sizeof(name)); memcpy(copy, name, length + 1u);
    if (!lsf_device_publish(&factory.pool, state->owner, ticket, LSF_DEVICE_VIRTIO_CORE_NAME)) {
        factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1); result = -EIO; goto out;
    }
    dev->dev.kobj.name = copy;
    result = 0;
out:
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

int lsf_factory_stream_virtio_core_name_return(const void *kobject, const void *name)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_view *r, *birth;
    struct lsf_prepaid_ticket ticket, parent;
    struct virtio_device *dev;
    unsigned long flags, base;
    unsigned int i;
    int kind = lsf_factory_stream_virtio_core_classify(kobject, 1), result = -EOPNOTSUPP;
    if (kind <= 0) return kind; /* Existing non-VIRTIO private cleanup unchanged. */
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    birth = lsf_stream_virtio_core_parent_locked(state, kobject, 1, &parent, &dev);
    if (!birth || !lsf_stream_rx_address_locked(name) || state->vp_tail_task != current ||
        birth->deferred != LSF_PREPAID_QUEUED || dev->dev.kobj.name != name ||
        birth->security_cache_identity != (LSF_STREAM_VP_CORE_INITIALIZED | LSF_STREAM_VP_RELEASE_SEEN |
                                            LSF_STREAM_VP_TAIL_ACTIVE)) goto poison;
    base = (unsigned long)page_address(factory.pages);
    for (i = 1; i < LSF_ALLOCATION_SLOTS; ++i) {
        r = &factory.pool.records[i];
        if (r->offset != (unsigned long)name - base) continue;
        ticket = (struct lsf_prepaid_ticket){i, r->generation};
        if (!lsf_device_record(&factory.pool, state->owner, ticket, LSF_DEVICE_VIRTIO_CORE_NAME) ||
            r->bytes != (((sizeof("virtio") + 10u) + 63u) & ~63ull) ||
            r->deferred != LSF_PREPAID_PUBLISHED || r->cache_bucket != parent.slot ||
            r->cache_anchor != parent.generation) goto poison;
        dev->dev.kobj.name = NULL; /* Original cleanup already cached name. */
        if (!lsf_device_queue(&factory.pool, state->owner, ticket, LSF_DEVICE_VIRTIO_CORE_NAME) ||
            !lsf_device_finish(&factory.pool, state->owner, ticket, LSF_DEVICE_VIRTIO_CORE_NAME)) goto poison;
        result = 1; goto out;
    }
poison:
    factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1);
out:
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

/* SPDX-License-Identifier: GPL-2.0-only */
/* Second CLOSED typed container for the existing grouped registration route.
 * The legacy source fields named pci_slot/generation identify the actual
 * container ticket, whose kind is read from the original record. For this
 * route that ticket is VIRTIO, never a fabricated PCI birth. All children
 * remain parented to VIRTIO until real native/RCU returns complete. */
#include <net/lsf_stream_constructor_private.h>

static struct lsf_factory_device_firmware *
lsf_stream_virtio_registration_parent_locked(struct lsf_device_registration_source source)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_view *r, *pci;
    struct lsf_prepaid_ticket ticket = {source.pci_slot, source.pci_generation}, same;
    struct lsf_factory_device_firmware *firmware;
    const void *address;
    unsigned int bits;
    lockdep_assert_held(&pool_lock);
    state = lsf_stream_rx_current_locked();
    if (!state || !factory.pages || !ticket.slot || ticket.slot >= LSF_ALLOCATION_SLOTS ||
        !ticket.generation || !state->virtio) return NULL;
    r = lsf_device_record(&factory.pool, state->owner, ticket, LSF_DEVICE_VIRTIO);
    if (!r || r->bytes != state->vp_extent ||
        r->security_cache_location != LSF_STREAM_VP_PARENT_HELD) return NULL;
    address = (char *)page_address(factory.pages) + r->offset;
    if (state->virtio != address || lsf_stream_vp_record_locked(state, address, &same) != r ||
        same.slot != ticket.slot || same.generation != ticket.generation) return NULL;
    bits = r->security_cache_identity;
    if (r->deferred == LSF_PREPAID_PUBLISHED) {
        if (bits != LSF_STREAM_VP_CORE_INITIALIZED &&
            bits != (LSF_STREAM_VP_CORE_INITIALIZED | LSF_STREAM_VP_TAIL_ACTIVE)) return NULL;
    } else if (r->deferred == LSF_PREPAID_QUEUED) {
        if (bits != (LSF_STREAM_VP_CORE_INITIALIZED | LSF_STREAM_VP_RELEASE_SEEN |
                     LSF_STREAM_VP_TAIL_ACTIVE) &&
            bits != (LSF_STREAM_VP_CORE_INITIALIZED | LSF_STREAM_VP_RELEASE_SEEN |
                     LSF_STREAM_VP_TAIL_DONE)) return NULL;
    } else return NULL;
    /* Original immutable ancestry and positive native PCI reference suffice
     * after the embedded VIRTIO payload's last native use. No dead dev/name
     * or kobject is read during a later child's actual return. */
    pci = lsf_device_record(&factory.pool, state->owner,
        (struct lsf_prepaid_ticket){r->cache_bucket, r->cache_anchor}, LSF_DEVICE_PCI);
    if (!pci || pci->bytes < sizeof(struct pci_dev)) return NULL;
    firmware = lsf_factory_device_firmware_for_pci(
        (char *)page_address(factory.pages) + pci->offset,
        (struct lsf_prepaid_ticket){r->cache_bucket, r->cache_anchor});
    return firmware;
}

/* Called only after generic record/container validation. Original PCI current
 * rules stay unchanged; VIRTIO additionally requires this exact one-shot bind
 * and the original absolute bootstrap deadline before ANY new child birth. */
static int lsf_stream_virtio_registration_bind_locked(struct lsf_device_registration_source source)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_view *r;
    lockdep_assert_held(&pool_lock);
    if (!source.pci_slot || source.pci_slot >= LSF_ALLOCATION_SLOTS) return 0;
    r = &factory.pool.records[source.pci_slot];
    if (r->kind != LSF_DEVICE_VIRTIO) return 1; /* Original PCI arm validates itself. */
    state = lsf_stream_rx_current_locked();
    return state && lsf_stream_bind_current_locked(state) &&
        r->deferred == LSF_PREPAID_PUBLISHED &&
        r->security_cache_identity == LSF_STREAM_VP_CORE_INITIALIZED;
}

int lsf_factory_stream_virtio_registration_kobject(const void *kobject,
    struct lsf_device_registration_source *copy)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_view *r;
    struct lsf_prepaid_ticket ticket;
    struct virtio_device *dev;
    unsigned long flags;
    int kind, result = -EOPNOTSUPP;
    if (!copy) return -EINVAL;
    kind = lsf_factory_stream_virtio_core_classify(kobject, 1);
    if (kind <= 0) return kind;
    spin_lock_irqsave(&pool_lock, flags);
    state = lsf_stream_rx_current_locked();
    r = lsf_stream_virtio_core_parent_locked(state, kobject, 1, &ticket, &dev);
    if (!r || !lsf_stream_bind_current_locked(state) ||
        r->deferred != LSF_PREPAID_PUBLISHED ||
        r->security_cache_identity != LSF_STREAM_VP_CORE_INITIALIZED ||
        !dev->dev.kobj.state_initialized ||
        !lsf_prepaid_stream_vp_device_known(dev, state->pci)) goto poison;
    *copy = (struct lsf_device_registration_source){
        .address = dev, .kind = LSF_DEVICE_VIRTIO,
        .slot = ticket.slot, .generation = ticket.generation,
        .pci_slot = ticket.slot, .pci_generation = ticket.generation,
    };
    result = 1;
    goto out;
poison:
    factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1);
out:
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

/* SPDX-License-Identifier: GPL-2.0-only */
/* Included in the original lib/idr.c, only for CONFIG_LSF_STREAM_FACTORY.
 * Closed proc/virtio callers authenticate their actual static IDA and original
 * constructor before entry. This primitive supplies no ownership or authority.
 *
 * Select ONE original marked candidate under the original IDA XArray lock.
 * Reuse its bitmap, replace its inline value, or use the empty inline root.
 * A missing subtree, value-to-bitmap upgrade, or unavailable candidate fails:
 * no bitmap allocator, xas_nomem, retry, or new XArray node can be reached.
 * Conservative failure does not advertise other global free IDs as capacity.
 */
int lsf_prepaid_stream_ida_alloc_existing(struct ida *ida,
    unsigned int min, unsigned int max)
{
    XA_STATE(xas, &ida->xa, min / IDA_BITMAP_BITS);
    struct ida_bitmap *bitmap;
    unsigned int bit = min % IDA_BITMAP_BITS;
    unsigned long flags;
    int result = -ENOSPC;

    /* Preserve original ida_alloc_range inclusive bounds and INT_MAX clamp. */
    if ((int)min < 0)
        return -ENOSPC;
    if ((int)max < 0)
        max = INT_MAX;
    if (min > max)
        return -ENOSPC;

    xas_lock_irqsave(&xas, flags);
    bitmap = xas_find_marked(&xas, max / IDA_BITMAP_BITS, XA_FREE_MARK);
    if (!xas_valid(&xas) || xas.xa_index > max / IDA_BITMAP_BITS)
        goto out;
    if (xas.xa_index > min / IDA_BITMAP_BITS)
        bit = 0;
    if (xas.xa_index * IDA_BITMAP_BITS + bit > max)
        goto out;

    /* The valid root slot (xa_node==NULL, index zero) is already inside the
     * static IDA. xas_expand at index/order zero returns shift zero without
     * allocating; allow_root is true for a value. No empty non-root slot is
     * admitted, so xas_create cannot need a new node.
     */
    if (!bitmap) {
        if (xas.xa_node || xas.xa_index || bit >= BITS_PER_XA_VALUE)
            goto out;
        xas_store(&xas, xa_mk_value(1UL << bit));
        goto stored;
    }

    /* IDA entries are single-index leaves. A malformed/internal cursor is not
     * a bitmap or an invitation to create its missing descendants.
     */
    if ((xas.xa_node && xas.xa_node->shift) || xa_is_internal(bitmap))
        goto out;

    if (xa_is_value(bitmap)) {
        unsigned long value = xa_to_value(bitmap);

        if (bit >= BITS_PER_XA_VALUE)
            goto out;
        bit = find_next_zero_bit(&value, BITS_PER_XA_VALUE, bit);
        if (bit >= BITS_PER_XA_VALUE ||
            xas.xa_index * IDA_BITMAP_BITS + bit > max)
            goto out;
        /* A validated existing root/leaf slot is replaced at the SAME index.
         * No tree expansion or value-to-bitmap conversion is performed.
         */
        xas_store(&xas, xa_mk_value(value | (1UL << bit)));
        goto stored;
    }

    bit = find_next_zero_bit(bitmap->bitmap, IDA_BITMAP_BITS, bit);
    if (bit >= IDA_BITMAP_BITS ||
        xas.xa_index * IDA_BITMAP_BITS + bit > max)
        goto out;
    __set_bit(bit, bitmap->bitmap);
    if (bitmap_full(bitmap->bitmap, IDA_BITMAP_BITS))
        xas_clear_mark(&xas, XA_FREE_MARK);
    result = xas.xa_index * IDA_BITMAP_BITS + bit;
    goto out;

stored:
    /* An existing exact slot makes this error unreachable for the two valid
     * IDAs. Never invoke xas_nomem or a fallback allocator even on an error.
     */
    result = xas_error(&xas);
    if (!result)
        result = xas.xa_index * IDA_BITMAP_BITS + bit;
out:
    xas_unlock_irqrestore(&xas, flags);
    return result;
}

/* SPDX-License-Identifier: GPL-2.0-only */
/* Included in the original lib/radix-tree.c for the private constructor.
 * The exact typed caller has already authenticated its original kernfs IDR
 * and holds the original IDR mutation lock. No Root adopts global nodes.
 */
void __rcu **lsf_prepaid_stream_idr_get_free_existing(
    struct radix_tree_root *root, struct radix_tree_iter *iter,
    unsigned long max)
{
    struct radix_tree_node *node = NULL, *child;
    void __rcu **slot = (void __rcu **)&root->xa_head;
    unsigned long maxindex, start = iter->next_index;
    unsigned int shift, offset = 0;

    if (!is_idr(root))
        return ERR_PTR(-EINVAL);
    shift = radix_tree_load_root(root, &child, &maxindex);
    /* Original idr_get_free would extend a full/out-of-range root here.
     * An IDR needs node metadata even for its first slot: an empty root is
     * genuine missing capacity, unlike IDA's inline value optimisation.
     */
    if (!radix_tree_tagged(root, IDR_FREE) || start > max ||
        start > maxindex || !radix_tree_is_internal_node(child))
        return ERR_PTR(-ENOSPC);

    while (shift) {
        shift -= RADIX_TREE_MAP_SHIFT;
        /* The original missing-child allocation is a pre-effect refusal.
         * No radix_tree_extend, node allocator, preload, or retry is called.
         */
        if (!child || !radix_tree_is_internal_node(child))
            return ERR_PTR(-ENOSPC);

        node = entry_to_node(child);
        offset = radix_tree_descend(node, &child, start);
        if (!tag_get(node, IDR_FREE, offset)) {
            offset = radix_tree_find_next_bit(node, IDR_FREE, offset + 1);
            start = next_index(start, node, offset);
            if (start > max || start == 0)
                return ERR_PTR(-ENOSPC);
            while (offset == RADIX_TREE_MAP_SIZE) {
                offset = node->offset + 1;
                node = node->parent;
                /* Reaching beyond the existing root would require growth. */
                if (!node)
                    return ERR_PTR(-ENOSPC);
                shift = node->shift;
            }
            child = rcu_dereference_raw(node->slots[offset]);
        }
        slot = &node->slots[offset];
    }

    /* Only a tagged, empty, existing leaf slot is a usable ID. Iter state is
     * untouched on every refusal. The original caller publishes its pointer,
     * count and free-tag updates through radix_tree_iter_replace/tag_clear.
     */
    if (!node || node->shift || !tag_get(node, IDR_FREE, offset) ||
        rcu_dereference_raw(*slot))
        return ERR_PTR(-ENOSPC);

    iter->index = start;
    if (node)
        iter->next_index = 1 + min(max, (start | node_maxindex(node)));
    else
        iter->next_index = 1;
    iter->node = node;
    set_iter_tags(iter, node, offset, IDR_FREE);

    return slot;
}

/* SPDX-License-Identifier: GPL-2.0-only */
/* Included in actual x86 ioremap.c after its original functions. The actual
 * native caller/default wrappers below are cloned with full-declaration/body
 * inverse checks. Their physical validity/RAM/cache/encryption/trace rules
 * remain native; only funded view/PAT/PTE ownership is substituted. */
#include <net/lsf_stream_constructor_mmio_private.h>
#include <net/lsf_stream_constructor_mapping_private.h>

static bool lsf_stream_ioremap_no_cpa_growth(u64 physical)
{
    /* Exact early-return predicates from the pinned memtype_kernel_map_sync.
     * The real function is still called below, never replaced by fake zero.
     * Global RAM/resource-writer closure remains a qualification gate. */
    return physical > __pa(high_memory - 1) || !page_is_ram(physical >> PAGE_SHIFT);
}

static int lsf_stream_ioremap_cancel(struct lsf_stream_mmio_view *view)
{
    int result;
    if (lsf_factory_stream_mmio_owned(view, LSF_STREAM_MMIO_CANCEL) != 1)
        return -EOPNOTSUPP;
    result = lsf_prepaid_stream_mmio_cancel(view);
    if (result != 1) return result;
    result = lsf_prepaid_stream_memtype_free(view->pci, view->pat);
    if (result) {
        lsf_factory_stream_constructor_retain_unknown();
        return result;
    }
    return lsf_factory_stream_mmio_finish(view);
}

static void __iomem *
lsf_stream_ioremap_caller(struct pci_dev *pci, resource_size_t phys_addr, unsigned long size,
		 enum page_cache_mode pcm, void *caller, bool encrypted)
{
	unsigned long offset, vaddr;
	resource_size_t last_addr;
	const resource_size_t unaligned_phys_addr = phys_addr;
	const unsigned long unaligned_size = size;
	struct ioremap_desc io_desc;
	struct lsf_stream_mmio_view *area;
	struct memtype *pat = NULL;
	enum page_cache_mode new_pcm;
	pgprot_t prot;
	int retval;
	void __iomem *ret_addr;

	/* Don't allow wraparound or zero size */
	last_addr = phys_addr + size - 1;
	if (!size || last_addr < phys_addr)
		return NULL;

	if (!phys_addr_valid(phys_addr)) {
		printk(KERN_WARNING "ioremap: invalid physical address %llx\n",
		       (unsigned long long)phys_addr);
		WARN_ON_ONCE(1);
		return NULL;
	}

	__ioremap_check_mem(phys_addr, size, &io_desc);

	/*
	 * Don't allow anybody to remap normal RAM that we're using..
	 */
	if (io_desc.flags & IORES_MAP_SYSTEM_RAM) {
		WARN_ONCE(1, "ioremap on RAM at %pa - %pa\n",
			  &phys_addr, &last_addr);
		return NULL;
	}

	/*
	 * Mappings have to be page-aligned
	 */
	offset = phys_addr & ~PAGE_MASK;
	phys_addr &= PAGE_MASK;
	size = PAGE_ALIGN(last_addr+1) - phys_addr;

	/*
	 * Mask out any bits not part of the actual physical
	 * address, like memory encryption bits.
	 */
	phys_addr &= PHYSICAL_PAGE_MASK;

	retval = lsf_prepaid_stream_memtype_reserve(pci, phys_addr, (u64)phys_addr + size,
					pcm, &new_pcm, &pat);
	if (retval) {
		printk(KERN_ERR "ioremap memtype_reserve failed %d\n", retval);
		return NULL;
	}

	if (pcm != new_pcm) {
		if (!is_new_memtype_allowed(phys_addr, size, pcm, new_pcm)) {
			printk(KERN_ERR
		"ioremap error for 0x%llx-0x%llx, requested 0x%x, got 0x%x\n",
				(unsigned long long)phys_addr,
				(unsigned long long)(phys_addr + size),
				pcm, new_pcm);
			goto err_free_memtype;
		}
		pcm = new_pcm;
	}

	/*
	 * If the page being mapped is in memory and SEV is active then
	 * make sure the memory encryption attribute is enabled in the
	 * resulting mapping.
	 * In TDX guests, memory is marked private by default. If encryption
	 * is not requested (using encrypted), explicitly set decrypt
	 * attribute in all IOREMAPPED memory.
	 */
	prot = PAGE_KERNEL_IO;
	if ((io_desc.flags & IORES_MAP_ENCRYPTED) || encrypted)
		prot = pgprot_encrypted(prot);
	else
		prot = pgprot_decrypted(prot);

	switch (pcm) {
	case _PAGE_CACHE_MODE_UC:
	default:
		prot = __pgprot(pgprot_val(prot) |
				cachemode2protval(_PAGE_CACHE_MODE_UC));
		break;
	case _PAGE_CACHE_MODE_UC_MINUS:
		prot = __pgprot(pgprot_val(prot) |
				cachemode2protval(_PAGE_CACHE_MODE_UC_MINUS));
		break;
	case _PAGE_CACHE_MODE_WC:
		prot = __pgprot(pgprot_val(prot) |
				cachemode2protval(_PAGE_CACHE_MODE_WC));
		break;
	case _PAGE_CACHE_MODE_WT:
		prot = __pgprot(pgprot_val(prot) |
				cachemode2protval(_PAGE_CACHE_MODE_WT));
		break;
	case _PAGE_CACHE_MODE_WB:
		break;
	}

	/*
	 * Ok, go for it..
	 */
	area = lsf_factory_stream_mmio_allocate(pci, phys_addr, size, offset, prot, pat);
	if (!area)
		goto err_free_memtype;
	vaddr = area->virtual_start;

	/* Preserve the real native sync call only for its source-known
	 * no-CPA-growth branch. Unknown RAM/direct-map changes refuse. */
	if (!lsf_stream_ioremap_no_cpa_growth(phys_addr))
		goto err_free_area;

	if (memtype_kernel_map_sync(phys_addr, size, pcm)) {
		lsf_factory_stream_constructor_retain_unknown();
		return NULL; /* Unexpected global effect: retain all paid owners. */
	}

	if (lsf_prepaid_stream_mmio_map(area) != 1)
		goto err_free_area;

	ret_addr = (void __iomem *) (vaddr + offset);
	mmiotrace_ioremap(unaligned_phys_addr, unaligned_size, ret_addr);

	/*
	 * Check if the request spans more than any BAR in the iomem resource
	 * tree.
	 */
	if (iomem_map_sanity_check(unaligned_phys_addr, unaligned_size))
		pr_warn("caller %pS mapping multiple BARs\n", caller);

	return ret_addr;
err_free_area:
	(void)lsf_stream_ioremap_cancel(area);
	return NULL;
err_free_memtype:
	if (lsf_prepaid_stream_memtype_free(pci, pat))
		lsf_factory_stream_constructor_retain_unknown();
	return NULL;
}

void __iomem *lsf_prepaid_stream_ioremap(struct pci_dev *pci, resource_size_t phys_addr, unsigned long size)
{
	/*
	 * Ideally, this should be:
	 *	pat_enabled() ? _PAGE_CACHE_MODE_UC : _PAGE_CACHE_MODE_UC_MINUS;
	 *
	 * Till we fix all X drivers to use ioremap_wc(), we will use
	 * UC MINUS. Drivers that are certain they need or can already
	 * be converted over to strong UC can use ioremap_uc().
	 */
	enum page_cache_mode pcm = _PAGE_CACHE_MODE_UC_MINUS;
	if (lsf_factory_stream_mmio_pci_selected(pci) != 1) return NULL;

	return lsf_stream_ioremap_caller(pci, phys_addr, size, pcm,
				__builtin_return_address(0), false);
}

int lsf_prepaid_stream_iounmap(volatile void __iomem *address)
{
    struct lsf_stream_mmio_view *view;
    int result;
    if (!lsf_prepaid_stream_mmio_private_address((const void __force *)address))
        return lsf_factory_stream_mmio_task() ? -EOPNOTSUPP : 0;
    result = lsf_factory_stream_mmio_lookup((const void __force *)address, &view);
    if (result != 1) return result; /* Unknown private NEVER reaches ordinary unmap. */
    mmiotrace_iounmap(address); /* Actual native notification after owner proof. */
    result = lsf_prepaid_stream_mmio_unmap(view);
    if (result != 1) return result;
    result = lsf_prepaid_stream_memtype_free(view->pci, view->pat);
    if (result) {
        lsf_factory_stream_constructor_retain_unknown();
        return result;
    }
    return lsf_factory_stream_mmio_finish(view);
}

