/* SPDX-License-Identifier: GPL-2.0-only */
/* Included after actual memtype_interval.c. Called under the ORIGINAL
 * memtype_lock, from the private PAT free function only. Global range erasure
 * must never choose an owned interval on behalf of another mapping. */
#ifndef CONFIG_X86_PAT
#error "the private constructor uses the selected native PAT interval implementation"
#endif
int lsf_prepaid_stream_memtype_erase_owned(struct memtype *entry)
{
    struct memtype *candidate;
    int result;
    result = lsf_factory_stream_mapping_can_unlink(entry, LSF_STREAM_MAPPING_PAT);
    if (result != 1) return result < 0 ? result : -EOPNOTSUPP;
    /* Actual complete type/extent was proved before these payload reads.
     * Exact identity, not only overlapping [start,end], is required. Native
     * global PAT permits multiple interval records for the same range. */
    if (entry->start >= entry->end) return -EINVAL;
    candidate = interval_iter_first(&memtype_rbroot, entry->start, entry->end - 1u);
    while (candidate && candidate != entry)
        candidate = interval_iter_next(candidate, entry->start, entry->end - 1u);
    if (candidate != entry) return -EINVAL;
    interval_remove(entry, &memtype_rbroot);
    RB_CLEAR_NODE(&entry->rb);
    result = lsf_factory_stream_mapping_unlinked(entry, LSF_STREAM_MAPPING_PAT);
    return result == 1 ? 1 : -EOPNOTSUPP;
}

/* SPDX-License-Identifier: GPL-2.0-only */
/* Included in actual x86 PAT memtype.c. The real type, sanitize/MTRR/conflict
 * rules and original mutation lock are used; no duplicated type/layout or
 * substituted cache mode is supplied by a caller. Ordinary bodies stay exact. */
#ifndef CONFIG_X86_PAT
#error "the private constructor uses the selected native PAT interval implementation"
#endif

int lsf_prepaid_stream_pat_geometry(unsigned long *bytes, unsigned long *alignment)
{
    *bytes = sizeof(struct memtype);
    *alignment = __alignof__(struct memtype);
    return 1;
}

int lsf_prepaid_stream_memtype_reserve(struct pci_dev *pci, u64 start, u64 end,
    enum page_cache_mode req_type, enum page_cache_mode *new_type, struct memtype **owned)
{
    struct memtype *entry_new;
    enum page_cache_mode actual_type;
    int is_range_ram, err;
    if (!owned || start >= end) return -EINVAL;
    *owned = NULL;
    switch (req_type) {
    case _PAGE_CACHE_MODE_UC: case _PAGE_CACHE_MODE_UC_MINUS:
    case _PAGE_CACHE_MODE_WB: case _PAGE_CACHE_MODE_WC:
    case _PAGE_CACHE_MODE_WT: case _PAGE_CACHE_MODE_WP:
        break;
    default:
        return -EINVAL;
    }
    start = sanitize_phys(start);
    end = sanitize_phys(end - 1) + 1;
    if (start >= end || lsf_factory_stream_mapping_range(pci, start, end) != 1)
        return -EOPNOTSUPP;

    if (!pat_enabled()) {
        if (new_type) *new_type = req_type;
        return 0; /* Genuine native no-record branch, not a fabricated zero. */
    }
    if (x86_platform.is_untracked_pat_range(start, end)) {
        if (new_type) *new_type = _PAGE_CACHE_MODE_WB;
        return 0;
    }
    actual_type = pat_x_mtrr_type(start, end, req_type);
    if (new_type) *new_type = actual_type;
    is_range_ram = pat_pagerange_is_ram(start, end);
    /* This closed PCI-control MMIO route does not lend authority to mutate
     * RAM cacheability flags. The ordinary RAM API remains unchanged. */
    if (is_range_ram) return is_range_ram < 0 ? -EINVAL : -EOPNOTSUPP;

    entry_new = lsf_factory_stream_mapping_allocate(pci, LSF_STREAM_MAPPING_PAT,
        sizeof(*entry_new), __alignof__(*entry_new), start, end);
    if (!entry_new) return -ENOMEM;
    entry_new->start = start;
    entry_new->end = end;
    entry_new->type = actual_type;
    spin_lock(&memtype_lock);
    err = memtype_check_insert(entry_new, new_type);
    if (err) {
        /* Native failure before insertion can return the actual record. */
        (void)lsf_factory_stream_mapping_return(entry_new, LSF_STREAM_MAPPING_PAT);
        spin_unlock(&memtype_lock);
        return err;
    }
    if (lsf_factory_stream_mapping_linked(entry_new, LSF_STREAM_MAPPING_PAT) != 1) {
        spin_unlock(&memtype_lock);
        lsf_factory_stream_constructor_retain_unknown();
        return -EOPNOTSUPP; /* Native insertion succeeded: retain exact interval. */
    }
    spin_unlock(&memtype_lock);
    *owned = entry_new; /* Exact native record, retained for exact-pointer erase. */
    return 0;
}

int lsf_prepaid_stream_memtype_free(struct pci_dev *pci, struct memtype *entry)
{
    int result;
    /* The source-owned mapping caller may supply NULL only for a successful
     * native no-record reserve branch. NULL after an ERROR is not a no-birth
     * witness, and this local return never discharges any bank/Root record. */
    if (!entry) return 0;
    if (lsf_factory_stream_mapping_parent(pci, entry, LSF_STREAM_MAPPING_PAT) != 1)
        return -EOPNOTSUPP;
    spin_lock(&memtype_lock);
    result = lsf_prepaid_stream_memtype_erase_owned(entry);
    spin_unlock(&memtype_lock);
    if (result != 1) return result < 0 ? result : -EIO;
    result = lsf_factory_stream_mapping_return(entry, LSF_STREAM_MAPPING_PAT);
    return result == 1 ? 0 : -EIO;
}

