/* Included after the original pci-sysfs.c bodies for the private factory.
 * The original ordinary declarations/bodies remain unchanged. Bank helpers
 * authenticate complete typed extents before invoking the payload validator.
 */
#if !defined(HAVE_PCI_MMAP) && !defined(ARCH_GENERIC_PCI_MMAP_RESOURCE)
#error "the private PCI resource-file profile requires the native mmap implementation"
#endif

int lsf_prepaid_stream_pci_attr_geometry(unsigned int wc,
    unsigned long *bytes, unsigned long *alignment)
{
    if (wc > 1 || !bytes || !alignment)
        return 0;
    *bytes = sizeof(struct bin_attribute) + (wc ? 13UL : 10UL);
    *alignment = __alignof__(struct bin_attribute);
    return 1;
}

/* Caller first proves a LIVE exact PCI_ATTR extent and its actual PCI parent.
 * Compare native handler identities; never call any handler for validation.
 * This is a creation/registration check, not a substitute for final-use proof.
 */
int lsf_prepaid_stream_pci_attr_valid(const struct pci_dev *pdev,
    const void *address, unsigned int num, unsigned int wc)
{
    const struct bin_attribute *attr = address;
    struct bin_attribute expected = {0};
    char name[13];
    unsigned int name_bytes;

    if (!pdev || !attr || num >= PCI_STD_NUM_BARS || wc > 1 ||
        attr->attr.name != (const char *)(attr + 1))
        return 0;
    if (wc) {
        sprintf(name, "resource%u_wc", num);
        name_bytes = 13;
        expected.mmap = pci_mmap_resource_wc;
    } else {
        sprintf(name, "resource%u", num);
        name_bytes = 10;
        if (pci_resource_flags(pdev, num) & IORESOURCE_IO) {
            expected.read = pci_read_resource_io;
            expected.write = pci_write_resource_io;
            if (arch_can_pci_mmap_io())
                expected.mmap = pci_mmap_resource_uc;
        } else {
            expected.mmap = pci_mmap_resource_uc;
        }
    }
    if (expected.mmap) {
        expected.f_mapping = iomem_get_mapping;
        expected.llseek = pci_llseek_resource;
    }
    return !memcmp(attr->attr.name, name, name_bytes) &&
        attr->attr.mode == 0600 &&
        attr->size == pci_resource_len(pdev, num) &&
        attr->private == (void *)(unsigned long)num &&
        attr->read == expected.read && attr->write == expected.write &&
        attr->mmap == expected.mmap && attr->f_mapping == expected.f_mapping &&
        attr->llseek == expected.llseek;
}

int lsf_prepaid_stream_pci_create_attr(struct pci_dev *pdev, int num,
    int write_combine)
{
    /* Allocate the actual native attribute and its original piggyback name. */
    int name_len = write_combine ? 13 : 10;
    struct bin_attribute *res_attr;
    char *res_attr_name;
    int retval;

    if (num < 0 || num >= PCI_STD_NUM_BARS ||
        (write_combine != 0 && write_combine != 1) ||
        lsf_factory_stream_bind_selected(pdev) != 1 ||
        lsf_factory_stream_probe_current(pdev) != 1)
        return -EOPNOTSUPP;

    res_attr = lsf_factory_stream_pci_attr_allocate(pdev, num, write_combine,
        sizeof(*res_attr) + name_len, __alignof__(*res_attr));
    if (!res_attr)
        return -ENOMEM;

    res_attr_name = (char *)(res_attr + 1);

    sysfs_bin_attr_init(res_attr);
    if (write_combine) {
        sprintf(res_attr_name, "resource%d_wc", num);
        res_attr->mmap = pci_mmap_resource_wc;
    } else {
        sprintf(res_attr_name, "resource%d", num);
        if (pci_resource_flags(pdev, num) & IORESOURCE_IO) {
            res_attr->read = pci_read_resource_io;
            res_attr->write = pci_write_resource_io;
            if (arch_can_pci_mmap_io())
                res_attr->mmap = pci_mmap_resource_uc;
        } else {
            res_attr->mmap = pci_mmap_resource_uc;
        }
    }
    if (res_attr->mmap) {
        res_attr->f_mapping = iomem_get_mapping;
        /* Keep native mapping/seek semantics and its original callback order. */
        res_attr->llseek = pci_llseek_resource;
    }
    res_attr->attr.name = res_attr_name;
    res_attr->attr.mode = 0600;
    res_attr->size = pci_resource_len(pdev, num);
    res_attr->private = (void *)(unsigned long)num;
    retval = sysfs_create_bin_file(&pdev->dev.kobj, res_attr);
    if (retval) {
        /* The original failed-create edge did not publish either alias. */
        lsf_factory_stream_pci_attr_return(pdev, res_attr);
        return retval;
    }

    if (write_combine)
        pdev->res_attr_wc[num] = res_attr;
    else
        pdev->res_attr[num] = res_attr;

    return 0;
}

void lsf_prepaid_stream_pci_remove_resource_files(struct pci_dev *pdev)
{
    int i;

    if (lsf_factory_stream_bind_selected(pdev) != 1)
        return;
    for (i = 0; i < PCI_STD_NUM_BARS; i++) {
        struct bin_attribute *res_attr;

        res_attr = pdev->res_attr[i];
        if (res_attr) {
            if (lsf_factory_stream_pci_attr_owned(pdev, res_attr, i, 0) != 1)
                return;
            sysfs_remove_bin_file(&pdev->dev.kobj, res_attr);
            /* Failed partial construction may be followed by normal teardown.
             * Clear the owned alias before the real descriptor is returned.
             */
            pdev->res_attr[i] = NULL;
            lsf_factory_stream_pci_attr_return(pdev, res_attr);
        }

        res_attr = pdev->res_attr_wc[i];
        if (res_attr) {
            if (lsf_factory_stream_pci_attr_owned(pdev, res_attr, i, 1) != 1)
                return;
            sysfs_remove_bin_file(&pdev->dev.kobj, res_attr);
            pdev->res_attr_wc[i] = NULL;
            lsf_factory_stream_pci_attr_return(pdev, res_attr);
        }
    }
}

