/* Included after the original fs/proc/generic.c bodies. All four private
 * clones below are projected from their FULL original declarations/bodies;
 * ordinary proc allocation/registration/free code is not replaced. */

int lsf_prepaid_stream_proc_geometry(unsigned long *bytes, unsigned long *alignment)
{
    if (!SIZEOF_PDE || !SIZEOF_PDE_INLINE_NAME) return -EOPNOTSUPP;
    *bytes = SIZEOF_PDE;
    *alignment = __alignof__(struct proc_dir_entry);
    return 0;
}

int lsf_prepaid_stream_proc_free(struct proc_dir_entry *pde)
{
    int kind = lsf_factory_stream_proc_classify(pde);
    if (kind <= 0) {
        if (kind < 0) lsf_factory_stream_constructor_retain_unknown();
        return kind;
    }
    /* No additional native allocation or parent pointer read. The original
     * last pde_put (or exact failed private constructor) owns this object. */
    if (pde->name != pde->inline_name || !S_ISREG(pde->mode) ||
        pde->namelen + 1u > SIZEOF_PDE_INLINE_NAME ||
        !lsf_prepaid_stream_pci_proc_ops_known(pde->proc_ops) ||
        !lsf_factory_stream_proc_payload(pde, pde->data)) {
        lsf_factory_stream_constructor_retain_unknown();
        return -EOPNOTSUPP; /* Unknown exact record and bank remain charged. */
    }
    return lsf_factory_stream_proc_return(pde);
}

/* Source-generated full native clones are inserted HERE before this entry. */

struct proc_dir_entry *lsf_prepaid_stream_proc_create(struct pci_dev *pci,
    const char *name, struct proc_dir_entry *parent, const struct proc_ops *ops)
{
    struct proc_dir_entry *p;
    char expected[16];
    int length;
    if (lsf_prepaid_stream_pci_proc_current(pci, parent, ops) != 1) return NULL;
    length = snprintf(expected, sizeof(expected), "%02x.%x", PCI_SLOT(pci->devfn), PCI_FUNC(pci->devfn));
    if (length <= 0 || length >= sizeof(expected) || length + 1u > SIZEOF_PDE_INLINE_NAME ||
        strnlen(name, sizeof(expected)) != length || memcmp(name, expected, length + 1u))
        return NULL;
    p = lsf_stream_constructor_proc_create_reg(pci, name,
        S_IFREG | S_IRUGO | S_IWUSR, &parent, pci);
    if (!p) return NULL;
    p->proc_ops = ops;
    return lsf_stream_constructor_proc_register(parent, p);
}

