/* Included after the actual kernel/resource.c bodies. Native insertion,
 * conflict, revoke and release order remain real. No MUXED waiter allocation
 * or early memblock/ordinary-slab free behavior is changed. */
#include <linux/overflow.h>

int lsf_prepaid_stream_resource_geometry(unsigned long *bytes, unsigned long *alignment)
{
    *bytes = sizeof(struct resource) + sizeof("virtio-pci-modern");
    *alignment = __alignof__(struct resource);
    return 1;
}

struct resource *lsf_prepaid_stream_request_region(struct pci_dev *pci,
    struct resource *parent, resource_size_t start, resource_size_t n,
    const char *name, int flags)
{
    struct resource *res;
    resource_size_t end;
    char *owned_name;
    int ret;
    /* The actual closed modern caller supplies this native name. Pay for its
     * copy in the SAME typed extent, rather than borrow caller storage. */
    if (!name || strnlen(name, sizeof("virtio-pci-modern")) != sizeof("virtio-pci-modern") - 1u ||
        memcmp(name, "virtio-pci-modern", sizeof("virtio-pci-modern")) ||
        (parent != &iomem_resource && parent != &ioport_resource) ||
        (flags & ~IORESOURCE_EXCLUSIVE) || !n || check_add_overflow(start, n, &end))
        return NULL;
    res = lsf_factory_stream_mapping_allocate(pci, LSF_STREAM_MAPPING_RESOURCE,
        sizeof(*res) + sizeof("virtio-pci-modern"), __alignof__(*res), start, end);
    if (!res) return NULL;
    owned_name = (char *)(res + 1);
    memcpy(owned_name, name, sizeof("virtio-pci-modern"));

    write_lock(&resource_lock);
    ret = __request_region_locked(res, parent, start, n, owned_name, flags);
    if (!ret && lsf_factory_stream_mapping_linked(res, LSF_STREAM_MAPPING_RESOURCE) != 1) {
        write_unlock(&resource_lock);
        lsf_factory_stream_constructor_retain_unknown();
        return NULL; /* Native insertion succeeded: NEVER treat it as no birth. */
    }
    write_unlock(&resource_lock);

    if (ret) {
        free_resource(res); /* Exact failed-constructor typed return or retention. */
        return NULL;
    }
    if (parent == &iomem_resource)
        revoke_iomem(res); /* Original security operation, never a no-op substitute. */
    return res;
}

/* SPDX-License-Identifier: GPL-2.0-only */
/* Included after the actual private static window object. The three real
 * page arrays are embedded in that SAME object and accounted by its actual
 * sizeof/alignment in the ORIGINAL retained bootstrap remainder. None is a
 * Root-bank leaf or a dynamically adopted native ancestor. */
#if CONFIG_PGTABLE_LEVELS != 5 || defined(CONFIG_PARAVIRT_XXL)
#error "private static ancestry requires the selected native x86 paging hooks"
#endif
static_assert(sizeof(lsf_stream_vwindow.p4d) == PAGE_SIZE);
static_assert(sizeof(lsf_stream_vwindow.pud) == PAGE_SIZE);
static_assert(sizeof(lsf_stream_vwindow.pmd) == PAGE_SIZE);

static bool __init lsf_stream_vwindow_early_gap(unsigned long address)
{
    struct vm_struct *vm;
    unsigned long end, limit;
    if (address < VMALLOC_START || address > VMALLOC_END - PMD_SIZE ||
        !IS_ALIGNED(address, PMD_SIZE) ||
        check_add_overflow(address, PMD_SIZE, &end)) return false;
    for (vm = vmlist; vm; vm = vm->next) {
        if (!vm->size || check_add_overflow((unsigned long)vm->addr, vm->size, &limit))
            return false;
        if (address < limit && (unsigned long)vm->addr < end) return false;
    }
    return true;
}

static bool __init lsf_stream_vwindow_static_zero(void)
{
    unsigned int i;
    for (i = 0; i < ARRAY_SIZE(lsf_stream_vwindow.p4d); ++i)
        if (p4d_val(lsf_stream_vwindow.p4d[i])) return false;
    for (i = 0; i < ARRAY_SIZE(lsf_stream_vwindow.pud); ++i)
        if (pud_val(lsf_stream_vwindow.pud[i])) return false;
    for (i = 0; i < ARRAY_SIZE(lsf_stream_vwindow.pmd); ++i)
        if (pmd_val(lsf_stream_vwindow.pmd[i])) return false;
    return true;
}

static int __init lsf_stream_vwindow_preprovision(void)
{
    struct vm_struct *vm = &lsf_stream_vwindow.vm;
    unsigned long address, step = PGDIR_SIZE, next, flags;
    pgd_t *pgd;
    p4d_t *p4d;
    pud_t *pud;
    unsigned int slot;
    /* Source-pinned start_kernel -> mm_core_init -> vmalloc_init precedes
     * rest_init and smp_init. Refuse rather than assume that boot lifetime. */
    if (lsf_stream_vwindow.registered || lsf_stream_vwindow.ancestors_published ||
        vmap_initialized || system_state != SYSTEM_BOOTING ||
        num_online_cpus() != 1 || init_mm.pgd != swapper_pg_dir ||
        !lsf_stream_vwindow_static_zero() || step < PMD_SIZE ||
        !is_power_of_2(step) ||
        check_add_overflow(VMALLOC_START, step - 1u, &address)) return 0;
    address &= ~(step - 1u);
    /* Native hardware root width bounds this search. It is not a new Root,
     * connection or prototype limit. No populated ancestry is copied/adopted.
     * native_pgd_val is deliberate: pgd_none() is false when L5 is folded. */
    for (slot = 0; slot < PTRS_PER_PGD; ++slot) {
        if (address > VMALLOC_END - PMD_SIZE) return 0;
        pgd = pgd_offset_k(address);
        if (pgd_index(address) >= KERNEL_PGD_BOUNDARY &&
            !native_pgd_val(READ_ONCE(*pgd)) && lsf_stream_vwindow_early_gap(address))
            break;
        if (check_add_overflow(address, step, &next) || next <= address) return 0;
        address = next;
    }
    if (slot == PTRS_PER_PGD) return 0;

    /* This original helper inserts this already-proved free interval in the
     * real native vmlist and checks its neighbors. register_early cannot be
     * given a starting hint, so use add_early rather than pretending its first
     * free PMD interval has an originally empty native root slot. */
    vm->addr = (void *)address;
    vm->size = vm->requested_size = PMD_SIZE;
    vm->flags = VM_IOREMAP | VM_NO_GUARD;
    vm_area_add_early(vm);
    kasan_populate_early_vm_area_shadow(vm->addr, vm->size);
    WRITE_ONCE(lsf_stream_vwindow.registered, 1);

    spin_lock_irqsave(&init_mm.page_table_lock, flags);
    pgd = pgd_offset_k(address);
    if (native_pgd_val(READ_ONCE(*pgd))) {
        spin_unlock_irqrestore(&init_mm.page_table_lock, flags);
        return 0; /* Virtual reservation stays retained; never adopt a race. */
    }
    pud = &lsf_stream_vwindow.pud[pud_index(address)];
    /* Children are initialized BEFORE the native top-level publication.
     * All three pages have static Node lifetime, even when L5 is folded.
     * Their one-time native directory accounting is never refunded on Root
     * return. The later PTE page must still come from the original arena. */
    mm_inc_nr_pmds(&init_mm);
    pud_populate(&init_mm, pud, lsf_stream_vwindow.pmd);
    if (pgtable_l5_enabled()) {
        p4d = &lsf_stream_vwindow.p4d[p4d_index(address)];
        mm_inc_nr_puds(&init_mm);
        p4d_populate(&init_mm, p4d, lsf_stream_vwindow.pud);
        smp_wmb();
        pgd_populate(&init_mm, pgd, lsf_stream_vwindow.p4d);
    } else {
        /* Native folded helper aliases this exact still-zero static root
         * entry; it does not follow a present foreign table. */
        p4d = p4d_offset(pgd, address);
        mm_inc_nr_puds(&init_mm);
        smp_wmb();
        p4d_populate(&init_mm, p4d, lsf_stream_vwindow.pud);
    }
    WRITE_ONCE(lsf_stream_vwindow.ancestors_published, 1);
    spin_unlock_irqrestore(&init_mm.page_table_lock, flags);
    /* At this boot point no non-init mm has been created. Native x86
     * pgd_ctor subsequently copies the actual kernel entries from swapper.
     * No device PTE or present leaf was installed and no live mapping was
     * changed, so this is not an unmap/TLB-retirement witness. */
    return 1;
}

