int lsf_prepaid_stream_mmio_geometry(unsigned long *bytes, unsigned long *alignment,
    unsigned long *start, unsigned long *limit)
{
    if (!bytes || !alignment || !start || !limit ||
        !READ_ONCE(lsf_stream_vwindow.registered) ||
        !READ_ONCE(lsf_stream_vwindow.imported) ||
        !READ_ONCE(lsf_stream_vwindow.ancestors_published)) return -EOPNOTSUPP;
