static pte_t *lsf_stream_mmio_ptes_locked(struct lsf_stream_mmio_view *view,
    unsigned int operation, unsigned long *first, unsigned long *count)
{
    pmd_t *parent;
    pte_t *leaf;
    unsigned long start = (unsigned long)lsf_stream_vwindow.vm.addr, delta;
    lockdep_assert_held(&init_mm.page_table_lock);
    if (lsf_factory_stream_mmio_owned(view, operation) != 1) return NULL;
    parent = lsf_stream_vwindow_parent_locked();
    if (!parent || !pmd_present(*parent) || pmd_leaf(*parent) || pmd_bad(*parent)) return NULL;
    leaf = (void *)pmd_page_vaddr(*parent);
    if (lsf_factory_stream_mmio_leaf(view, leaf, operation) != 1) return NULL;
    if (view->virtual_start < start || !PAGE_ALIGNED(view->virtual_start) ||
        !PAGE_ALIGNED(view->bytes) || !PAGE_ALIGNED(view->physical_start) ||
        (pgprot_val(view->protection) & _PAGE_USER)) return NULL;
    delta = view->virtual_start - start;
    *first = delta >> PAGE_SHIFT;
    *count = view->bytes >> PAGE_SHIFT;
    if (!*count || *first >= PTRS_PER_PTE || *count > PTRS_PER_PTE - *first) return NULL;
    return leaf;
}

static bool lsf_stream_mmio_empty(pte_t *leaf, unsigned long first, unsigned long count)
{
    unsigned long i;
    for (i = 0; i < count; ++i)
        if (pte_val(ptep_get(&leaf[first+i]))) return false;
    return true;
}

static bool lsf_stream_mmio_exact(pte_t *leaf, struct lsf_stream_mmio_view *view,
    unsigned long first, unsigned long count)
{
    unsigned long i;
    u64 pfn = view->physical_start >> PAGE_SHIFT;
    pgprot_t prot = pgprot_nx(view->protection);
    for (i = 0; i < count; ++i) {
        pte_t actual = ptep_get(&leaf[first+i]);
        pte_t expected = pfn_pte(pfn+i, prot);
        /* Only real hardware A/D changes are tolerated. Unknown software,
         * PFN, user permission or cache/encryption changes retain the view. */
        if ((pte_val(actual) ^ pte_val(expected)) & ~(_PAGE_ACCESSED | _PAGE_DIRTY))
            return false;
    }
    return true;
}

int lsf_prepaid_stream_mmio_map(struct lsf_stream_mmio_view *view)
{
    pte_t *leaf;
    pgprot_t prot;
    u64 pfn;
    unsigned long flags, first, count, i, start, end;
    int result = -EOPNOTSUPP;
    if (!in_task() || irqs_disabled() || in_atomic() ||
        lsf_factory_stream_mmio_owned(view, LSF_STREAM_MMIO_MAP) != 1) return result;
    spin_lock_irqsave(&init_mm.page_table_lock, flags);
    leaf = lsf_stream_mmio_ptes_locked(view, LSF_STREAM_MMIO_MAP, &first, &count);
    if (!leaf || !lsf_stream_mmio_empty(leaf, first, count)) goto out;
    start = view->virtual_start; end = start + view->bytes;
    pfn = view->physical_start >> PAGE_SHIFT;
    prot = pgprot_nx(view->protection); /* Actual native vmap_page_range rule. */
    for (i = 0; i < count; ++i)
        set_pte_at(&init_mm, start + (i << PAGE_SHIFT), &leaf[first+i], pfn_pte(pfn+i, prot));
    spin_unlock_irqrestore(&init_mm.page_table_lock, flags);
    if (PGTBL_PTE_MODIFIED & ARCH_PAGE_TABLE_SYNC_MASK)
        arch_sync_kernel_mappings(start, end);
    flush_cache_vmap(start, end);
    result = kmsan_ioremap_page_range(start, end, view->physical_start,
        view->protection, PAGE_SHIFT);
    if (result) {
        lsf_factory_stream_constructor_retain_unknown();
        return result; /* PTE effects already occurred: NEVER cancel as no birth. */
    }
    return lsf_factory_stream_mmio_transition(view, 0u, 1u);
out:
    spin_unlock_irqrestore(&init_mm.page_table_lock, flags);
    return result;
}

int lsf_prepaid_stream_mmio_cancel(struct lsf_stream_mmio_view *view)
{
    pte_t *leaf;
    unsigned long flags, first, count;
    int result = -EOPNOTSUPP;
    if (!in_task() || irqs_disabled() || in_atomic() ||
        lsf_factory_stream_mmio_owned(view, LSF_STREAM_MMIO_CANCEL) != 1) return result;
    spin_lock_irqsave(&init_mm.page_table_lock, flags);
    leaf = lsf_stream_mmio_ptes_locked(view, LSF_STREAM_MMIO_CANCEL, &first, &count);
    if (leaf && lsf_stream_mmio_empty(leaf, first, count)) result = 1;
    spin_unlock_irqrestore(&init_mm.page_table_lock, flags);
    /* The monotonic original virtual cursor never reuses this range. Actual
     * zero PTEs and the before-map record state witness no mapping effect. */
    return result == 1 ? lsf_factory_stream_mmio_transition(view, 0u, 3u) : result;
}

int lsf_prepaid_stream_mmio_unmap(struct lsf_stream_mmio_view *view)
{
    pte_t *leaf;
    unsigned long flags, first, count, i, start, end;
    int result = -EOPNOTSUPP;
    if (!in_task() || irqs_disabled() || in_atomic() ||
        lsf_factory_stream_mmio_owned(view, LSF_STREAM_MMIO_UNMAP) != 1) return result;
    /* Preserve actual ordinary safety/cache/sanitizer operations outside MM
     * and metadata locks. The fixed non-sanitizer/debug profile takes native
     * disabled branches; no replacement success callback is invented. */
    start = view->virtual_start; end = start + view->bytes;
    debug_check_no_locks_freed((void *)start, view->bytes);
    debug_check_no_obj_freed((void *)start, view->bytes);
    kmsan_iounmap_page_range(start, end);
    flush_cache_vunmap(start, end);
    spin_lock_irqsave(&init_mm.page_table_lock, flags);
    leaf = lsf_stream_mmio_ptes_locked(view, LSF_STREAM_MMIO_UNMAP, &first, &count);
    if (!leaf || !lsf_stream_mmio_exact(leaf, view, first, count)) goto out;
    for (i = 0; i < count; ++i)
        pte_clear(&init_mm, start + (i << PAGE_SHIFT), &leaf[first+i]);
    spin_unlock_irqrestore(&init_mm.page_table_lock, flags);
    if (PGTBL_PTE_MODIFIED & ARCH_PAGE_TABLE_SYNC_MASK)
        arch_sync_kernel_mappings(start, end);
    /* Same synchronous native API as the source-reviewed full flush. No
     * factory/pool/init_mm lock is held. This is an inner driver-unmap route,
     * so it does NOT recursively acquire a CPU-hotplug reader lock. No leaf
     * physical page returns here; the separate final leaf detach freezes the
     * CPU set and revalidates every context/descendant before its return. */
    flush_tlb_all();
    return lsf_factory_stream_mmio_transition(view, 1u, 2u);
out:
    spin_unlock_irqrestore(&init_mm.page_table_lock, flags);
    return result;
}

