#define LSF_STREAM_CONSTRUCTOR_VWINDOW_PRIVATE_H
/* A compiled type measurement only. It grants no mapping, page-table,
 * bootstrap funding, Root ownership or address authority. */
int lsf_prepaid_stream_vwindow_static_geometry(unsigned long *, unsigned long *);
#endif

/* SPDX-License-Identifier: GPL-2.0-only */
/* Included at the end of the real private vmalloc fragment, after the actual
 * static ancestor object/hooks. The record callbacks authenticate an exact
 * Root-bank page BEFORE any page contents are read. No ordinary table is
 * adopted and no native operation runs while pool_lock is held. */
#include <net/lsf_stream_constructor_pte_private.h>
#include <linux/cpu.h>
#include <linux/preempt.h>
#include <linux/irqflags.h>
#include <asm/tlbflush.h>
static_assert(sizeof(pte_t) * PTRS_PER_PTE == PAGE_SIZE);

static pmd_t *lsf_stream_vwindow_parent_locked(void)
{
    unsigned long address = (unsigned long)lsf_stream_vwindow.vm.addr;
    pgd_t *pgd;
    p4d_t *p4d;
    pud_t *pud;
    pmd_t *pmd;
    lockdep_assert_held(&init_mm.page_table_lock);
    if (!READ_ONCE(lsf_stream_vwindow.registered) ||
        !READ_ONCE(lsf_stream_vwindow.imported) ||
        !READ_ONCE(lsf_stream_vwindow.ancestors_published) ||
        init_mm.pgd != swapper_pg_dir || !IS_ALIGNED(address, PMD_SIZE)) return NULL;
    pgd = pgd_offset_k(address);
    if (!pgd_present(*pgd) || pgd_bad(*pgd)) return NULL;
    if (pgtable_l5_enabled() &&
        pgd_page_vaddr(*pgd) != (unsigned long)lsf_stream_vwindow.p4d) return NULL;
    p4d = p4d_offset(pgd, address);
    if ((pgtable_l5_enabled() && p4d != &lsf_stream_vwindow.p4d[p4d_index(address)]) ||
        !p4d_present(*p4d) || p4d_bad(*p4d) ||
        p4d_pgtable(*p4d) != lsf_stream_vwindow.pud) return NULL;
    pud = pud_offset(p4d, address);
    if (pud != &lsf_stream_vwindow.pud[pud_index(address)] ||
        !pud_present(*pud) || pud_leaf(*pud) || pud_bad(*pud) ||
        pud_pgtable(*pud) != lsf_stream_vwindow.pmd) return NULL;
    pmd = pmd_offset(pud, address);
    return pmd == &lsf_stream_vwindow.pmd[pmd_index(address)] ? pmd : NULL;
}

static bool lsf_stream_vwindow_leaf_empty(const pte_t *leaf)
{
    unsigned int i;
    for (i = 0; i < PTRS_PER_PTE; ++i)
        if (pte_val(READ_ONCE(leaf[i]))) return false;
    return true;
}

int lsf_prepaid_stream_pte_install(void *address)
{
    pte_t *leaf = address;
    pmd_t *parent;
    unsigned long flags;
    int result = -EOPNOTSUPP;
    if (!in_task() || irqs_disabled() || in_atomic()) return result;
    if (lsf_factory_stream_pte_owned(leaf, LSF_STREAM_PTE_INSTALL) != 1) return result;
    spin_lock_irqsave(&init_mm.page_table_lock, flags);
    parent = lsf_stream_vwindow_parent_locked();
    if (!parent || !pmd_none(*parent) ||
        lsf_factory_stream_pte_owned(leaf, LSF_STREAM_PTE_INSTALL) != 1 ||
        !lsf_stream_vwindow_leaf_empty(leaf)) goto out;
    /* Native kernel leaf allocation has no user PTE constructor. Actual
     * source-owned PAGE backing was zeroed and published before this hook. */
    smp_wmb();
    pmd_populate_kernel(&init_mm, parent, leaf);
    result = lsf_factory_stream_pte_transition(leaf, 0u, 1u);
    /* If the AFTER-effect witness fails, the native parent remains linked
     * and the original paid bank is retained, never labelled no birth. */
out:
    spin_unlock_irqrestore(&init_mm.page_table_lock, flags);
    return result;
}

int lsf_prepaid_stream_pte_detach(void *address)
{
    pte_t *leaf = address;
    pmd_t *parent;
    unsigned long flags;
    int result = -EOPNOTSUPP;
    if (!in_task() || irqs_disabled() || in_atomic()) return result;
    if (lsf_factory_stream_pte_owned(leaf, LSF_STREAM_PTE_UNLINK) != 1) return result;
    /* The sole source caller is the original normal-stop task, after the
     * native PCI-remove call returned, outside factory/pool/MM locks. It is
     * not a CPU-hotplug callback and holds no hotplug writer/read lock. */
    cpus_read_lock();
    spin_lock_irqsave(&init_mm.page_table_lock, flags);
    parent = lsf_stream_vwindow_parent_locked();
    if (!parent || !pmd_present(*parent) || pmd_leaf(*parent) || pmd_bad(*parent) ||
        pmd_page_vaddr(*parent) != (unsigned long)leaf ||
        lsf_factory_stream_pte_owned(leaf, LSF_STREAM_PTE_UNLINK) != 1 ||
        !lsf_stream_vwindow_leaf_empty(leaf)) goto out;
    pmd_clear(parent); /* Exact genuine parent, AFTER all actual leaf entries zero. */
    result = lsf_factory_stream_pte_transition(leaf, 1u, 2u);
out:
    spin_unlock_irqrestore(&init_mm.page_table_lock, flags);
    if (result == 1) {
        /* Actual ALL-online-CPU synchronous full flush: no mutable per-page
         * threshold or KVM remote multi-flush shortcut is used. No factory,
         * pool or init_mm lock is held. The original online set is stable.
         * Panic/lost return cannot reach the AFTER-completion witness. */
        flush_tlb_all();
        result = lsf_factory_stream_pte_transition(leaf, 2u, 3u);
    }
    cpus_read_unlock();
    return result;
}

/* SPDX-License-Identifier: GPL-2.0-only */
/* Included in the actual maintained mm/vmalloc.c before its free helpers.
 * A real EARLY VIRTUAL reservation only: no physical mapping or ownership of
 * pre-existing page tables is inferred. Both native metadata objects have
 * static kernel lifetime and NEVER enter a free/lazy/per-node pool. Their
 * actual compiled size is exposed separately for the original funding join;
 * this source increment does not claim that join or a usable MMIO path. */
#include <net/lsf_stream_constructor_vwindow_private.h>

#if !defined(CONFIG_X86_64) || defined(CONFIG_KASAN_VMALLOC)
#error "private early reservation requires the selected x86-64 non-KASAN-vmalloc profile"
#endif
static_assert(PAGE_SIZE == 4096);
static_assert(PMD_SIZE > PAGE_SIZE);

static struct {
    struct vm_struct vm;
    struct vmap_area va;
    unsigned int registered;
    unsigned int imported;
} lsf_stream_vwindow;

int lsf_prepaid_stream_vwindow_static_geometry(unsigned long *bytes,
    unsigned long *alignment)
{
    if (!bytes || !alignment) return -EINVAL;
    *bytes = sizeof(lsf_stream_vwindow);
    *alignment = __alignof__(lsf_stream_vwindow);
    return 1; /* Actual type facts, NOT a funding or mapping witness. */
}

static bool lsf_stream_vwindow_vm(const struct vm_struct *vm)
{
    return vm == &lsf_stream_vwindow.vm;
}

static bool lsf_stream_vwindow_va(const struct vmap_area *va)
{
    return va == &lsf_stream_vwindow.va;
}

static bool lsf_stream_vwindow_address(unsigned long address)
{
    unsigned long start;
    if (!READ_ONCE(lsf_stream_vwindow.registered)) return false;
    start = (unsigned long)lsf_stream_vwindow.vm.addr;
    return address >= start && address - start < PMD_SIZE;
}

static void __init lsf_stream_vwindow_register(void)
{
    struct vm_struct *vm = &lsf_stream_vwindow.vm;
    unsigned long address;
    if (WARN_ON_ONCE(lsf_stream_vwindow.registered || vmap_initialized)) return;
    vm->size = PMD_SIZE;
    vm->requested_size = PMD_SIZE;
    vm->flags = VM_IOREMAP | VM_NO_GUARD;
    /* This uses native randomized VMALLOC_START..END and chooses the first
     * PMD-aligned FREE interval, not a guessed address or an END promise.
     * The source-pinned selected CONFIG_KASAN_VMALLOC=n branch makes the
     * actual kasan_populate_early_vm_area_shadow call an empty inline. This
     * function is NOT claimed allocation-free for arbitrary KASAN profiles. */
    vm_area_register_early(vm, PMD_SIZE);
    address = (unsigned long)vm->addr;
    if (WARN_ON_ONCE(address < VMALLOC_START || address > VMALLOC_END - PMD_SIZE ||
        !IS_ALIGNED(address, PMD_SIZE))) return;
    WRITE_ONCE(lsf_stream_vwindow.registered, 1);
}

static struct vmap_area *__init lsf_stream_vwindow_import(struct vm_struct *vm)
{
    if (!lsf_stream_vwindow_vm(vm) || !lsf_stream_vwindow.registered ||
        lsf_stream_vwindow.imported || vm->size != PMD_SIZE ||
        vm->requested_size != PMD_SIZE || vm->flags != (VM_IOREMAP | VM_NO_GUARD) ||
        !IS_ALIGNED((unsigned long)vm->addr, PMD_SIZE)) return NULL;
    return &lsf_stream_vwindow.va;
}
